/* Original practice questions, aligned to the first-assessment-2025 syllabus. */
(() => {
  const bank = [], count = {};
  const fmt = (x, p = 3) => Number(x.toPrecision(p)).toString();
  const n = (x, unit = '') => {
    const value = fmt(x), scientific = value.match(/^(.+)e([+-]?\d+)$/);
    const shown = scientific ? '$' + scientific[1] + '\\times10^{' + Number(scientific[2]) + '}$' : value;
    return shown + (unit ? ' ' + unit : '');
  };
  function add(topic, prompt, options, explanation, difficulty = 'Standard', level) {
    const num = count[topic] = (count[topic] || 0) + 1;
    const answer = (num - 1) % 4;
    const shifted = options.map((_, j) => options[(j - answer + 4) % 4]);
    bank.push({ id: topic.replace('.', '') + '-' + String(num).padStart(3, '0'), topic,
      level: level || (['A.4', 'A.5', 'B.4'].includes(topic) ? 'HL' : 'Core'),
      difficulty, prompt, options: shifted, answer, explanation });
  }

  // A.1 Kinematics: interpretation, modelling and four independent numerical sets.
  [
    ['A runner completes one lap of a circular track and returns to the starting point. Which pair describes the distance and displacement?', ['Distance is positive; displacement is zero.', 'Both are zero.', 'Both equal the circumference.', 'Distance is zero; displacement is positive.'], 'Distance counts the complete path travelled. Displacement is final position minus initial position, so it is zero after one lap.'],
    ['What does the gradient of a displacement–time graph represent?', ['Velocity', 'Acceleration', 'Distance travelled', 'Resultant force'], 'Velocity is the rate of change of displacement, so it is the gradient of a displacement–time graph.'],
    ['What does the signed area under a velocity–time graph represent?', ['Displacement', 'Speed', 'Acceleration', 'Total distance in every case'], 'The integral of velocity over time is displacement. Negative areas subtract from positive areas; total distance requires the area under the speed–time graph.'],
    ['A velocity–time graph is a horizontal line below the time axis. Which description is correct?', ['Constant negative velocity and zero acceleration', 'Constant negative acceleration', 'The object is stationary.', 'The speed is increasing.'], 'The graph has zero gradient, so acceleration is zero. The negative ordinate gives constant velocity in the chosen negative direction.'],
    ['At the highest point of an ideal projectile launched at an angle above the horizontal, which statement is correct?', ['Vertical velocity is zero; acceleration is downward.', 'Both velocity and acceleration are zero.', 'Horizontal velocity is zero; acceleration is downward.', 'Acceleration is horizontal.'], 'Gravity acts throughout the flight. Only the vertical component of velocity becomes zero at the highest point; the horizontal component remains unchanged.'],
    ['Two balls leave the same height simultaneously: one is dropped and one is projected horizontally. Air resistance is negligible. Which lands first?', ['They land at the same time.', 'The dropped ball.', 'The projected ball.', 'The heavier ball, regardless of launch speed.'], 'Both begin with zero vertical velocity and have the same vertical acceleration and displacement. Horizontal motion does not affect the time to fall.'],
    ['Which condition is required to apply $v^2=u^2+2as$ over a whole interval?', ['Acceleration is constant over the interval.', 'Velocity is constant over the interval.', 'Initial velocity is zero.', 'Displacement is positive.'], 'The constant-acceleration equations assume a constant acceleration. Initial velocity can be non-zero and signed quantities may be negative.'],
    ['A car moves east while slowing down. Taking east as positive, what are the signs of velocity and acceleration?', ['Velocity positive, acceleration negative', 'Both positive', 'Both negative', 'Velocity negative, acceleration positive'], 'Velocity points east but the acceleration that reduces the speed points west. Speed decreases when velocity and acceleration have opposite signs.'],
    ['An object has zero instantaneous velocity. What can be inferred about its acceleration?', ['Its acceleration may be non-zero.', 'Its acceleration must be zero.', 'Its acceleration must be positive.', 'Its acceleration is undefined.'], 'At a turning point, such as the top of a vertical throw, velocity is momentarily zero while the acceleration remains downward.'],
    ['A projectile is launched and lands at the same height with negligible air resistance. Which pair of launch angles gives equal ranges at the same launch speed?', ['30° and 60°', '20° and 60°', '30° and 45°', '10° and 70°'], 'For equal launch and landing heights, range is proportional to $\\sin(2\\theta)$. Complementary angles have the same sine of twice the angle.'],
    ['A falling object reaches terminal speed in air. What is its acceleration at that time?', ['Zero', 'Equal to $g$ downward', 'Equal to $g$ upward', 'Increasing downward'], 'At terminal speed, the upward resistance and buoyancy balance weight. The resultant force and acceleration are zero although the object continues moving.'],
    ['Compared with an ideal projectile, what is a usual effect of air resistance on a projectile launched at an angle above the horizontal?', ['A smaller horizontal range', 'A constant horizontal speed', 'A perfectly symmetric parabolic trajectory', 'An upward acceleration at all times'], 'Air resistance has a component opposing horizontal motion and dissipates mechanical energy, reducing horizontal range for the same launch conditions.'],
    ['A displacement–time graph becomes progressively steeper in the positive direction. What does this indicate?', ['Positive velocity with increasing speed', 'Negative velocity with increasing speed', 'Constant positive velocity', 'Zero acceleration'], 'The gradient is positive and its magnitude increases. Therefore velocity is positive and speed increases.'],
    ['An object moves 6 m east then 8 m north. What is the magnitude of its displacement?', ['10 m', '14 m', '2 m', '48 m'], 'The perpendicular displacement components form a right triangle: $s=\\sqrt{6^2+8^2}=10$ m. The distance travelled is 14 m.'],
    ['For a velocity that changes continuously, how is instantaneous acceleration found graphically?', ['The gradient of the tangent to the velocity–time graph', 'The area under the velocity–time graph', 'The gradient of a chord over the entire journey', 'The height of the displacement–time graph'], 'Instantaneous acceleration is the derivative of velocity, represented by the tangent gradient at the instant. A chord gives average acceleration over an interval.'],
    ['A speed is calculated from $v=s/t$. The distance has a 2% uncertainty and the time a 3% uncertainty. What is the estimated percentage uncertainty in speed?', ['5%', '1%', '6%', '2.5%'], 'For a quotient, fractional uncertainties are added in the standard IB maximum-uncertainty treatment: $\\Delta v/v=\\Delta s/s+\\Delta t/t=5\\%$.']
  ].forEach(x => add('A.1', ...x));
  for (let i = 0; i < 4; i++) {
    const u = 2 + i, a = 2, t = 3 + i, v = u + a*t;
    add('A.1', `A trolley initially moves at ${u} m s⁻¹ and accelerates uniformly at ${a} m s⁻² for ${t} s. What is its final speed?`, [n(v,'m s⁻¹'), n(a*t,'m s⁻¹'), n(u+a,'m s⁻¹'), n(v*2,'m s⁻¹')], `Use $v=u+at=${u}+${a}(${t})=${v}$ m s⁻¹. Acceleration changes velocity; it is not itself a velocity.`);
    const acc = 2 + i, time = 4, dist = 0.5*acc*time*time;
    add('A.1', `An object starts from rest and accelerates uniformly at ${acc} m s⁻² for ${time} s. What distance does it travel?`, [n(dist,'m'), n(acc*time,'m'), n(2*dist,'m'), n(dist/4,'m')], `Since $u=0$, $s=at^2/2=${acc}\\times 4^2/2=${dist}$ m. The factor of one half accounts for the increasing speed.`);
    const speed = 10 + 5*i, stop = 2 + i, brake = speed*speed/(2*stop);
    add('A.1', `A vehicle travels at ${speed} m s⁻¹ before braking with constant deceleration of magnitude ${stop} m s⁻². What is its stopping distance?`, [n(brake,'m'), n(speed/stop,'m'), n(2*brake,'m'), n(brake/2,'m')], `Take forward as positive. With $v=0$ and $a=-${stop}$, $0=u^2+2as$, so $s=u^2/(2|a|)=${fmt(brake)}$ m.`);
    const height = 5*(i+1), vx = 8, fall = Math.sqrt(2*height/10), range = vx*fall;
    add('A.1', `A ball is projected horizontally at ${vx} m s⁻¹ from a height of ${height} m. Use $g=10$ m s⁻² and neglect air resistance. What is its horizontal range?`, [n(range,'m'), n(range*1.5,'m'), n(2*range,'m'), n(range/2,'m')], `Vertical motion gives $t=\\sqrt{2h/g}=${fmt(fall)}$ s. Horizontal speed is constant, so $x=v_xt=${fmt(range)}$ m.`, 'Standard');
    const initial = 3+i, final = 9+3*i, interval = 4, s = (initial+final)*interval/2;
    add('A.1', `A straight velocity–time line rises from ${initial} m s⁻¹ at 0 s to ${final} m s⁻¹ at ${interval} s. What is the displacement in this interval?`, [n(s,'m'), n(final*interval,'m'), n((final-initial)*interval/2,'m'), n(s/3,'m')], `The displacement is the trapezium area: $s=(u+v)t/2=(${initial}+${final})(${interval})/2=${s}$ m.`);
    const launch = 15+5*i, maxH = launch*launch/20;
    add('A.1', `A ball is thrown vertically upward at ${launch} m s⁻¹. Use $g=10$ m s⁻² and neglect air resistance. How high does it rise above its release point?`, [n(maxH,'m'), n(launch/10,'m'), n(2*maxH,'m'), n(maxH/2,'m')], `At maximum height $v=0$. Therefore $0=u^2-2gh$, and $h=u^2/(2g)=${fmt(maxH)}$ m.`);
  }

  [
    ['A book rests on a horizontal table. Which pair is a Newton’s third-law pair?', ['The table pushing up on the book and the book pushing down on the table', 'The weight of the book and the normal force on the book', 'The weight of the table and the weight of the book', 'The normal force on the book and air resistance on the book'], 'Third-law forces are equal and opposite forces on different bodies arising from the same interaction. Weight and normal force both act on the book and are not such a pair.'],
    ['A body moves in a straight line at constant velocity. What is the resultant force on it?', ['Zero', 'In the direction of motion', 'Opposite to the direction of motion', 'Equal to its momentum'], 'Constant velocity means zero acceleration. Newton’s second law then gives zero resultant force, even when individual forces act.'],
    ['A box is at rest on a rough horizontal surface. A small horizontal force is increased slowly while the box stays at rest. What happens to static friction?', ['It increases to balance the applied force until its limiting value.', 'It is always equal to $\\mu_sN$.', 'It is always zero until the box moves.', 'It decreases as the applied force increases.'], 'Static friction adjusts to prevent relative motion and satisfies $F_f\\leq\\mu_sN$. Equality applies only at impending sliding.'],
    ['For a small sphere moving slowly through a viscous fluid in the Stokes regime, how does drag change when speed doubles?', ['It doubles.', 'It halves.', 'It quadruples.', 'It is unchanged.'], 'Stokes’ law is $F_d=6\\pi\\eta rv$, so drag is directly proportional to speed when the fluid, sphere and flow regime are unchanged.'],
    ['A fully submerged object is moved deeper into a liquid of uniform density. What happens to its buoyant force?', ['It remains unchanged.', 'It increases in proportion to depth.', 'It decreases in proportion to depth.', 'It becomes zero.'], 'Buoyant force is the weight of displaced liquid, $F_b=\\rho Vg$. At fixed displaced volume and density it is independent of depth.'],
    ['Which quantity must be conserved in a collision when the net external impulse on the two-body system is negligible?', ['Total momentum', 'Total kinetic energy', 'The speed of each body', 'The momentum of each body separately'], 'Internal interaction forces cancel in the system momentum balance. Kinetic energy is conserved only for an elastic collision.'],
    ['Two objects stick together after colliding. How is this collision classified?', ['Perfectly inelastic', 'Perfectly elastic', 'A collision in which momentum cannot be conserved', 'A collision in which no energy is transformed'], 'Sticking is the defining feature of a perfectly inelastic collision. Total momentum can still be conserved, while kinetic energy is generally reduced.'],
    ['A ball bounces off a wall and reverses its velocity. Which change is necessarily relevant to its impulse?', ['The change in the signed momentum', 'Only the change in its speed', 'Only its final kinetic energy', 'Only the contact distance'], 'Impulse is $\\Delta p=m(v-u)$, using signed velocities. A reversal can produce a large momentum change even when the initial and final speeds match.'],
    ['For uniform circular motion, which direction does acceleration have?', ['Toward the centre of the circle', 'Along the instantaneous velocity', 'Away from the centre', 'It is zero because speed is constant.'], 'Velocity changes direction continuously. The acceleration causing this change is centripetal and points toward the centre.'],
    ['What does the area under a resultant-force–time graph equal?', ['Impulse', 'Work', 'Power', 'Acceleration'], 'The integral of force over time is impulse, equal to the change in momentum. Work instead involves force integrated over displacement.'],
    ['A spring follows Hooke’s law. What does the negative sign in $F=-kx$ express?', ['The force opposes the displacement from equilibrium.', 'The spring constant is negative.', 'The force always points downward.', 'The spring stores negative energy.'], 'A restoring force points toward the equilibrium position, opposite to the signed displacement. The spring constant and stored energy are positive.'],
    ['A person stands on a scale in a lift accelerating upward. How does the scale reading compare with the person’s weight?', ['It is greater than the weight.', 'It equals the weight.', 'It is less than the weight.', 'It is zero.'], 'The scale measures normal force. With upward positive, $N-mg=ma$, so $N=m(g+a)>mg$.'],
    ['A car rounds a level circular bend at constant speed. Which force usually supplies the required horizontal resultant force?', ['Static friction between tyres and road', 'The car’s weight alone', 'The upward normal force alone', 'A separate outward centrifugal force on the car'], 'The horizontal component of the real contact force, usually static friction for rolling tyres, provides the centripetal force.'],
    ['A stone on a string is just able to complete a vertical circle. At the top, when tension becomes zero, what supplies the centripetal force?', ['The stone’s weight', 'No force is required.', 'An outward force equal to its weight', 'The stone’s momentum'], 'At the limiting top point gravity alone supplies the inward force: $mg=mv^2/r$. Momentum is not a force.'],
    ['Why do airbags reduce the average force on an occupant during a given change of momentum?', ['They increase the stopping time.', 'They increase the momentum change.', 'They eliminate the impulse.', 'They make the occupant’s initial mass smaller.'], 'For a given impulse, $F_{average}=\\Delta p/\\Delta t$. Increasing the stopping time decreases the average force.'],
    ['A measured force is found using $F=mv^2/r$. Mass and radius have negligible uncertainty, while speed has 4% uncertainty. What is the percentage uncertainty in force?', ['8%', '4%', '2%', '16%'], 'For a power, fractional uncertainty is multiplied by the magnitude of the exponent. Because $F\\propto v^2$, the force uncertainty is $2\\times4\\%=8\\%$.']
  ].forEach(x=>add('A.2',...x));
  for(let i=0;i<4;i++) {
    const m=2+i,F=12+6*i,a=F/m;
    add('A.2',`A resultant force of ${F} N acts on a ${m} kg object of constant mass. What is its acceleration?`,[n(a,'m s⁻²'),n(F*m,'m s⁻²'),n(m/F,'m s⁻²'),n(a/2,'m s⁻²')],`Newton’s second law gives $a=F/m=${F}/${m}=${fmt(a)}$ m s⁻².`,'Foundation');
    const mass=2+i,mu=0.2+0.1*i,fr=mu*mass*10;
    add('A.2',`A ${mass} kg block slides on a horizontal surface with coefficient of dynamic friction ${fmt(mu)}. There are no other vertical forces. Use $g=10$ m s⁻². What is the friction magnitude?`,[n(fr,'N'),n(mu*mass,'N'),n(mass*15,'N'),n(fr*2,'N')],`The normal force is $N=mg=${mass*10}$ N. Sliding friction is $F_f=\\mu_dN=${fmt(mu)}(${mass*10})=${fmt(fr)}$ N.`);
    const ball=0.1*(i+1),speed=10,bounce=ball*2*speed;
    add('A.2',`A ball of mass ${fmt(ball)} kg moving at +${speed} m s⁻¹ rebounds at −${speed} m s⁻¹. What is the magnitude of its impulse?`,[n(bounce,'N s'),n(ball*speed,'N s'), '0 N s',n(bounce*2,'N s')],`The velocity change is $-${speed}-${speed}=-${2*speed}$ m s⁻¹. Thus $|\\Delta p|=m|\\Delta v|=${fmt(bounce)}$ N s.`);
    const mass1=1+i,mass2=2*mass1,speed1=6,common=mass1*speed1/(mass1+mass2);
    add('A.2',`A ${mass1} kg trolley moving at ${speed1} m s⁻¹ collides with a stationary ${mass2} kg trolley and they stick. External impulse is negligible. What is their common speed?`,[n(common,'m s⁻¹'),n(speed1,'m s⁻¹'),n(speed1/2,'m s⁻¹'),n(common/2,'m s⁻¹')],`Conservation of momentum gives $m_1u_1=(m_1+m_2)v$. Hence $v=${mass1}(${speed1})/${mass1+mass2}=${common}$ m s⁻¹.`);
    const vel=4+2*i,r=2,ac=vel*vel/r;
    add('A.2',`An object moves uniformly in a circle of radius ${r} m at ${vel} m s⁻¹. What is its centripetal acceleration?`,[n(ac,'m s⁻²'),n(vel/r,'m s⁻²'),n(ac*2,'m s⁻²'),n(ac/2,'m s⁻²')],`For circular motion $a=v^2/r=${vel}^2/${r}=${ac}$ m s⁻², directed toward the centre.`);
    const k=100+50*i,x=0.04,Fspring=k*x;
    add('A.2',`A spring of constant ${k} N m⁻¹ is stretched by ${x} m within its Hooke’s-law range. What is the magnitude of its restoring force?`,[n(Fspring,'N'),n(Fspring/2,'N'),n(k/x,'N'),n(Fspring*2,'N')],`Hooke’s law gives magnitude $F=kx=${k}(${x})=${Fspring}$ N. The force acts toward the equilibrium length.`);
  }

  [
    ['A force acts perpendicular to the displacement of its point of application. What work does it do?', ['Zero', 'The product of force and displacement', 'The product of force and speed', 'Negative work in every case'], '$W=Fs\\cos\\theta$. At $\\theta=90^\\circ$, the parallel component is zero and no work is done by that force.'],
    ['What is the work done by the resultant force on a particle equal to?', ['The change in its kinetic energy', 'Its final kinetic energy in every case', 'Its change in momentum', 'Its total potential energy'], 'The work–kinetic-energy theorem gives $W_{net}=\\Delta E_k$. Work by an individual force may instead transfer energy between kinetic and potential stores.'],
    ['For an object of fixed mass, what happens to kinetic energy when momentum doubles?', ['It quadruples.', 'It doubles.', 'It halves.', 'It is unchanged.'], '$E_k=p^2/(2m)$, so doubling momentum at fixed mass multiplies kinetic energy by four.'],
    ['A ball falls freely with negligible air resistance close to Earth. Which quantity remains constant?', ['Total mechanical energy', 'Gravitational potential energy', 'Kinetic energy', 'Momentum of the ball alone'], 'As height decreases, gravitational potential energy is converted to kinetic energy. Their sum is conserved when non-conservative forces do negligible work.'],
    ['What does the area under a force–extension graph for a spring represent?', ['Elastic potential energy stored', 'Spring constant', 'Momentum', 'Power'], 'Work stretching the spring is the integral of force with respect to extension. For a Hooke’s-law spring the triangular area is $kx^2/2$.'],
    ['A motor runs at a constant output power while lifting a load at constant speed. If the lifting force doubles, what happens to the speed?', ['It halves.', 'It doubles.', 'It quadruples.', 'It is unchanged.'], '$P=Fv$ for force parallel to velocity. At constant power, speed is inversely proportional to force.'],
    ['A machine has efficiency 0.75. What does this mean?', ['75% of the input energy becomes useful output energy.', '75% of the output energy is wasted.', 'The machine produces 25% more energy than it receives.', 'The output power must be 0.75 W.'], 'Efficiency is useful energy output divided by energy input. It is a ratio with no unit, and does not specify an absolute power.'],
    ['Why is mechanical energy reduced when a block slides to rest on a rough surface?', ['Mechanical energy is transferred to internal energy of the block and surroundings.', 'Energy is destroyed by friction.', 'Momentum is converted into a new type of energy.', 'The block’s mass disappears.'], 'Friction transfers energy from organized motion to microscopic internal energy. Total energy remains conserved when the surroundings are included.'],
    ['Two identical springs are stretched by $x$ and $2x$, within their elastic limits. What is the ratio of stored energies $E_{2x}/E_x$?', ['4', '2', '1/2', '8'], 'Elastic energy is $kx^2/2$. Doubling extension therefore multiplies the stored energy by four.'],
    ['A person carries a bag horizontally at constant height. In the ideal model, what work does the upward supporting force do on the bag?', ['Zero', 'Positive work equal to weight times horizontal distance', 'Negative work equal to weight times horizontal distance', 'Work equal to the bag’s momentum'], 'The upward supporting force is perpendicular to the horizontal displacement, so its work is zero in this idealized motion.'],
    ['What does fuel energy density expressed in J kg⁻¹ measure?', ['Energy released per unit mass of fuel', 'Mass released per unit energy', 'Energy released per unit time', 'Energy released per unit volume'], 'A mass-specific energy density divides available energy by fuel mass. A volume-specific value would instead have units J m⁻³.'],
    ['An ideal pendulum swings in a uniform gravitational field with no resistance. Where is its speed greatest?', ['At its lowest point', 'At its highest point', 'At every point equally', 'At the point of maximum potential energy'], 'At the lowest point gravitational potential energy is smallest, so kinetic energy and speed are greatest for the fixed total mechanical energy.'],
    ['A force on a moving body acts opposite to its displacement. What is the sign of the work it does?', ['Negative', 'Positive', 'Zero', 'It depends only on the body’s mass.'], 'The angle between force and displacement is $180^\\circ$, so $W=Fs\\cos180^\\circ=-Fs$. The force removes kinetic energy.'],
    ['Which unit is equivalent to one watt?', ['J s⁻¹', 'J s', 'N s', 'kg m s⁻¹'], 'Power is the rate of energy transfer, so the watt is one joule transferred per second.'],
    ['Two objects have equal momentum magnitudes. Object X has twice the mass of object Y. What is $E_{k,X}/E_{k,Y}$?', ['1/2', '2', '4', '1'], 'At fixed momentum $E_k=p^2/(2m)$, so kinetic energy is inversely proportional to mass. Doubling mass halves kinetic energy.'],
    ['A kinetic energy is calculated using $E_k=mv^2/2$. The mass has 2% uncertainty and speed has 3% uncertainty. What is the estimated percentage uncertainty in kinetic energy?', ['8%', '5%', '6%', '11%'], 'For products, fractional uncertainties add, with the power multiplying the speed uncertainty: $2\\%+2(3\\%)=8\\%$.']
  ].forEach(x=>add('A.3',...x));
  for(let i=0;i<4;i++) {
    const force=10+5*i,s=4,W=force*s*0.5;
    add('A.3',`A constant ${force} N force acts at 60° to a displacement of ${s} m. What work does the force do?`,[n(W,'J'),n(force*s,'J'),n(W/2,'J'),n(-W,'J')],`The component parallel to motion is $F\\cos60^\\circ=F/2$. Hence $W=Fs\\cos60^\\circ=${W}$ J.`);
    const m=2+i,v=4,energy=m*v*v/2;
    add('A.3',`A ${m} kg object moves at ${v} m s⁻¹. What is its kinetic energy?`,[n(energy,'J'),n(m*v,'J'),n(2*energy,'J'),n(energy/4,'J')],`$E_k=mv^2/2=${m}(4^2)/2=${energy}$ J.`,'Foundation');
    const mass=3+i,h=5,ep=mass*10*h;
    add('A.3',`A ${mass} kg load is raised vertically by ${h} m at constant speed. Use $g=10$ m s⁻². What is its increase in gravitational potential energy?`,[n(ep,'J'),n(mass*h,'J'),n(ep/2,'J'),n(ep*2,'J')],`In a uniform gravitational field $\\Delta E_p=mg\\Delta h=${mass}(10)(5)=${ep}$ J. Constant speed means no change in kinetic energy.`);
    const k=200+100*i,x=0.1,es=k*x*x/2;
    add('A.3',`A Hooke’s-law spring has constant ${k} N m⁻¹ and extension ${x} m. What elastic energy is stored relative to its unstretched state?`,[n(es,'J'),n(k*x,'J'),n(2*es,'J'),n(es/2,'J')],`$E_H=kx^2/2=${k}(0.1)^2/2=${fmt(es)}$ J. Force is not constant as the spring is stretched.`);
    const power=200+100*i,eta=0.6,useful=power*eta;
    add('A.3',`A motor receives ${power} W of electrical power and operates at 60% efficiency. What useful mechanical power does it deliver?`,[n(useful,'W'),n(power/eta,'W'),n(power-useful,'W'),n(power*0.3,'W')],`Efficiency is $P_{out}/P_{in}$. Thus $P_{out}=0.60(${power})=${useful}$ W. The remaining ${power-useful} W is dissipated.`);
    const fuel=2+i,density=30,energyMJ=fuel*density;
    add('A.3',`A fuel has a mass-specific energy density of ${density} MJ kg⁻¹. What energy is released by complete combustion of ${fuel} kg?`,[n(energyMJ,'MJ'),n(density/fuel,'MJ'),n(energyMJ/2,'MJ'),n(energyMJ*2,'MJ')],`Multiply energy per kilogram by mass: $E=q m=${density}(${fuel})=${energyMJ}$ MJ.`);
  }

  [
    ['A force acts along a line through a rotation axis. What is its torque about that axis?', ['Zero', 'Force multiplied by the radius', 'The same as the angular momentum', 'Infinite'], 'The perpendicular distance from the axis to the force’s line of action is zero. Hence $\\tau=Fr\\sin\\theta=0$.'],
    ['What conditions are needed for complete static equilibrium of a rigid body?', ['Zero resultant force and zero resultant torque', 'Zero resultant force only', 'Zero resultant torque only', 'Equal mass on both sides of every axis'], 'Translational equilibrium requires no resultant force. Rotational equilibrium independently requires no resultant torque.'],
    ['A rotating body’s mass is redistributed farther from its fixed axis. What happens to its moment of inertia?', ['It increases.', 'It decreases.', 'It is unchanged because mass is conserved.', 'It becomes zero.'], 'Moment of inertia is $I=\\sum mr^2$. Increasing distances of mass elements from the axis increases $I$, even at constant total mass.'],
    ['A skater pulls in their arms while external torque is negligible. What happens?', ['Moment of inertia decreases and angular speed increases.', 'Moment of inertia and angular speed both decrease.', 'Angular momentum increases.', 'Angular speed remains constant.'], 'Angular momentum $L=I\\omega$ is conserved. A reduction in $I$ therefore produces an increase in $\\omega$.'],
    ['A skater pulls in their arms and speeds up with negligible external torque. Why can rotational kinetic energy increase?', ['The skater does internal work while pulling in the arms.', 'Conservation of angular momentum requires energy creation.', 'The angular momentum must also increase.', 'Moment of inertia is converted into mass.'], 'The skater’s muscles do work using internal energy. At fixed $L$, $E_k=L^2/(2I)$ increases when $I$ decreases.'],
    ['What does the area under a torque–time graph represent?', ['Change in angular momentum', 'Angular displacement', 'Moment of inertia', 'Rotational kinetic energy'], 'Angular impulse is $\\int\\tau\\,dt=\\Delta L$, the rotational counterpart of linear impulse.'],
    ['What does the gradient of an angular velocity–time graph represent?', ['Angular acceleration', 'Torque in every case', 'Angular displacement', 'Moment of inertia'], 'Angular acceleration is the rate of change of angular velocity: $\\alpha=\\Delta\\omega/\\Delta t$ for a straight-line graph.'],
    ['A wheel rolls without slipping with centre speed $v$ and radius $r$. What is its angular speed?', ['$v/r$', '$vr$', '$r/v$', '$v^2/r$'], 'Rolling without slipping requires the rim speed relative to the centre to equal the centre’s translational speed, so $v=\\omega r$.'],
    ['Two bodies have equal masses but different mass distributions. Can they have different moments of inertia about parallel axes through their centres?', ['Yes, because moment of inertia depends on the distances of mass from the axis.', 'No, because moment of inertia depends only on total mass.', 'No, because each centre is on its axis.', 'Only if their angular speeds differ.'], 'Moment of inertia describes both mass and its distribution about a specified axis. Angular speed does not determine it.'],
    ['A rigid body rotates about a fixed axis at constant angular speed. What is the resultant torque about that axis?', ['Zero', 'Equal to $I\\omega$', 'Equal to the rotational kinetic energy', 'Increasing with time'], 'For constant moment of inertia, $\\tau=I\\alpha$. Constant angular speed means $\\alpha=0$, so the resultant torque is zero.'],
    ['A wheel’s angular speed doubles while its moment of inertia stays constant. How do angular momentum and rotational kinetic energy change?', ['Angular momentum doubles; kinetic energy quadruples.', 'Both double.', 'Both quadruple.', 'Angular momentum quadruples; kinetic energy doubles.'], '$L=I\\omega$ is linear in speed, whereas $E_k=I\\omega^2/2$ depends on its square.'],
    ['Two equal opposite parallel forces act at different points on a rigid body. What can they produce?', ['A non-zero torque with zero resultant force', 'A non-zero resultant force with zero torque in every case', 'No rotational effect in every case', 'An increase of mass'], 'Such a couple has zero resultant force but generally a non-zero moment because the forces have separated lines of action.'],
    ['Which SI unit is used for moment of inertia?', ['kg m²', 'kg m', 'N m', 'kg m² s⁻¹'], '$I=\\sum mr^2$, so its unit is mass times length squared. The unit kg m² s⁻¹ instead belongs to angular momentum.'],
    ['A uniform disk rotates while an identical stationary disk is gently coupled coaxially to it. External torque is negligible. What happens to total angular momentum?', ['It is conserved, although rotational kinetic energy decreases.', 'It halves because the final speed halves.', 'It doubles because the total inertia doubles.', 'It becomes zero.'], 'Coupling forces are internal to the two-disk system. Angular momentum is conserved; friction converts some rotational kinetic energy to internal energy.'],
    ['A point mass is moved from radius $r$ to radius $2r$ about the same axis. What happens to its contribution to moment of inertia?', ['It becomes four times as large.', 'It doubles.', 'It halves.', 'It is unchanged.'], 'The contribution is $mr^2$. Replacing $r$ with $2r$ multiplies it by $2^2=4$.'],
    ['A torque is calculated from $\\tau=Fr$ with a force perpendicular to the radius. Force has 3% uncertainty and radius 2% uncertainty. What is the percentage uncertainty in torque?', ['5%', '1%', '6%', '2.5%'], 'For a product, fractional uncertainties add. Thus the torque uncertainty is $3\\%+2\\%=5\\%$.']
  ].forEach(x=>add('A.4',...x));
  for(let i=0;i<4;i++) {
    const F=10+5*i,r=0.4,tau=F*r;
    add('A.4',`A ${F} N force acts perpendicular to a lever ${r} m from its pivot. What torque magnitude does it exert?`,[n(tau,'N m'),n(tau/2,'N m'),n(F/r,'N m'),n(tau*2,'N m')],`$\\tau=Fr\\sin90^\\circ=${F}(0.4)=${tau}$ N m.`,'Foundation');
    const inertia=2+i,torque=12+6*i,alpha=torque/inertia;
    add('A.4',`A wheel of moment of inertia ${inertia} kg m² experiences a resultant torque of ${torque} N m. What is its angular acceleration?`,[n(alpha,'rad s⁻²'),n(torque*inertia,'rad s⁻²'),n(inertia/torque,'rad s⁻²'),n(alpha/2,'rad s⁻²')],`For fixed inertia, $\\alpha=\\tau/I=${torque}/${inertia}=${fmt(alpha)}$ rad s⁻².`);
    const mass=1+i,radius=0.5,Im=2*mass*radius*radius;
    add('A.4',`Two point masses, each ${mass} kg, are fixed ${radius} m from a light rotation axis. What is their total moment of inertia?`,[n(Im,'kg m²'),n(Im/2,'kg m²'),n(2*mass*radius,'kg m²'),n(Im*4,'kg m²')],`Add both point-mass contributions: $I=2mr^2=2(${mass})(0.5)^2=${fmt(Im)}$ kg m².`);
    const Ii=4+i,wi=6,If=Ii/2,wf=Ii*wi/If;
    add('A.4',`A rotating system has moment of inertia ${Ii} kg m² and angular speed ${wi} rad s⁻¹. With negligible external torque, its inertia falls to ${If} kg m². What is its final angular speed?`,[n(wf,'rad s⁻¹'),n(wi/2,'rad s⁻¹'),n(wi,'rad s⁻¹'),n(wf*2,'rad s⁻¹')],`Angular momentum is conserved: $I_i\\omega_i=I_f\\omega_f$. Therefore $\\omega_f=${Ii}(6)/${If}=${wf}$ rad s⁻¹.`);
    const I=1+i,w=4,Ek=I*w*w/2;
    add('A.4',`A flywheel of moment of inertia ${I} kg m² rotates at ${w} rad s⁻¹. What is its rotational kinetic energy?`,[n(Ek,'J'),n(I*w,'J'),n(Ek*2,'J'),n(Ek/4,'J')],`$E_k=I\\omega^2/2=${I}(4^2)/2=${Ek}$ J.`);
    const angularA=2+i,time=3,angle=0.5*angularA*time*time;
    add('A.4',`A wheel starts from rest with constant angular acceleration ${angularA} rad s⁻². Through what angle does it turn in ${time} s?`,[n(angle,'rad'),n(angularA*time,'rad'),n(angle*2,'rad'),n(angle/2,'rad')],`With $\\omega_i=0$, $\\Delta\\theta=\\alpha t^2/2=${angularA}(3^2)/2=${angle}$ rad.`);
  }

  [
    ['Which reference frame is inertial?', ['A frame moving at constant velocity relative to another inertial frame', 'A frame rotating at constant angular speed', 'A frame accelerating uniformly', 'A frame fixed to a turning car'], 'An inertial frame is non-accelerating. Rotation and a change in either speed or direction imply acceleration.'],
    ['Which is a postulate of special relativity?', ['The speed of light in vacuum is the same for all inertial observers.', 'All observers agree on the time between every pair of events.', 'Light speed is added Galilei-style to the source speed.', 'The laws of physics hold only in a preferred rest frame.'], 'Special relativity postulates the equivalence of inertial frames for physical laws and the invariant vacuum speed of light.'],
    ['What is the proper time between two events?', ['The time measured in a frame where the events occur at the same position', 'The longest possible time in any frame', 'The time measured only by an Earth-based clock', 'The time measured in a frame where the events are simultaneous'], 'A clock present at both events measures proper time. In that clock’s inertial rest frame the events share one spatial position.'],
    ['What is the proper length of an object?', ['Its length measured in its own rest frame', 'Its shortest measured length', 'Its length measured only while moving at light speed', 'Its length measured without simultaneous endpoint positions'], 'Proper length is the rest-frame length. An observer relative to whom the object moves measures a contracted length along its direction of motion.'],
    ['A rod moves parallel to its length relative to an observer. Compared with its rest length, what length does that observer measure?', ['A shorter length', 'A greater length', 'The same length at every speed', 'Zero length at every non-zero speed'], 'Length contraction gives $L=L_0/\\gamma$, with $\\gamma>1$ for non-zero relative speed. Endpoint positions must be recorded simultaneously in the measuring frame.'],
    ['A rod moves perpendicular to its length. What does special relativity predict about its measured length along that perpendicular direction?', ['No length contraction in that direction', 'The same contraction as along the motion', 'A length increase by $\\gamma$', 'A length decrease to zero'], 'Length contraction applies to the component parallel to relative motion. Transverse dimensions are unchanged.'],
    ['Two spatially separated events are simultaneous in one inertial frame. Must they be simultaneous in every inertial frame?', ['No; simultaneity can depend on the frame.', 'Yes; only distances can change.', 'Yes; time is invariant.', 'No; one event must always cause the other.'], 'The Lorentz time transformation includes a position-dependent term. Spatially separated simultaneous events generally have different times in another moving frame.'],
    ['On a space–time diagram with vertical $ct$ and horizontal $x$, which world line describes an object at rest?', ['A vertical straight line', 'A horizontal straight line', 'A 45° line', 'A parabola opening upward'], 'For an object at rest, $x$ is constant while time increases, so the world line is parallel to the $ct$ axis.'],
    ['On equally scaled $ct$ and $x$ axes, what is the angle between a light ray’s world line and the time axis?', ['45°', '0°', '30°', '90°'], 'For light $x=ct$, so the horizontal and vertical changes have equal magnitude. Its world line is at 45° on equally scaled axes.'],
    ['What happens to the Lorentz factor as relative speed approaches the vacuum speed of light from below?', ['It increases without bound.', 'It approaches zero.', 'It approaches 1/2.', 'It becomes negative.'], '$\\gamma=1/\\sqrt{1-v^2/c^2}$. Its denominator approaches zero from above as $v\\to c$.'],
    ['Which quantity has the same value in all inertial frames?', ['The space–time interval between two events', 'The spatial separation of every pair of events', 'The time separation of every pair of events', 'The velocity of every massive object'], 'Lorentz transformations preserve $(\\Delta s)^2=(c\\Delta t)^2-(\\Delta x)^2$. Space and time separations separately generally change.'],
    ['Muon observations provide evidence for special relativity because many muons reach Earth’s surface despite short rest lifetimes. In Earth’s frame, how is this explained?', ['Their moving lifetimes are dilated.', 'Their proper lifetimes become zero.', 'Their speed exceeds $c$.', 'Their clocks run faster than stationary clocks.'], 'In Earth’s frame a moving muon’s lifetime is $\\gamma$ times its proper lifetime, allowing a greater travel distance before decay.'],
    ['In the muon’s rest frame, why can it reach the ground within its proper lifetime?', ['The atmosphere’s thickness along the motion is length-contracted.', 'Earth has no atmosphere in this frame.', 'Light travels faster in this frame.', 'The muon’s own proper lifetime is infinitely long.'], 'The approaching Earth and atmosphere are moving in the muon frame. Their longitudinal thickness is contracted, reducing the required travel distance.'],
    ['A spacecraft emits a light pulse forward. What speed does an inertial observer outside the spacecraft measure for the pulse in vacuum?', ['$c$', '$c$ plus the spacecraft speed', '$c$ minus the spacecraft speed', 'Zero if the spacecraft moves at constant velocity'], 'All inertial observers measure the same speed $c$ for light in vacuum, independently of the source motion.'],
    ['What limit does the Galilean approximation require for ordinary material-object velocity transformations?', ['Relative speeds much smaller than $c$', 'Relative speeds exactly equal to $c$', 'A Lorentz factor much greater than 1', 'Zero time in both frames'], 'When $v/c$ is very small, $\\gamma\\approx1$ and relativistic corrections are negligible. The Lorentz transformations reduce approximately to the Galilean ones.'],
    ['For a pair of events with a positive squared interval $(c\\Delta t)^2-(\\Delta x)^2$, what type of separation is this?', ['Timelike', 'Spacelike', 'Lightlike', 'Always simultaneous'], 'A positive squared interval means $c|\\Delta t|>|\\Delta x|$. A subluminal object can, in principle, connect the events, so the separation is timelike.']
  ].forEach(x=>add('A.5',...x));
  for(let i=0;i<4;i++) {
    const v=10+5*i,u=30+5*i,rel=u-v;
    add('A.5',`Two vehicles move east. Relative to the road, X travels at ${u} m s⁻¹ and Y at ${v} m s⁻¹. In the Galilean approximation, what is X’s velocity in Y’s frame?`,[n(rel,'m s⁻¹ east'),n(u+v,'m s⁻¹ east'),n(u,'m s⁻¹ east'),n(v,'m s⁻¹ west')],`Use $u'=u-v=${u}-${v}=${rel}$ m s⁻¹ east. At these speeds the Galilean approximation is excellent.`);
    const gamma=[1.25,5/3,2,2.5][i],beta=Math.sqrt(1-1/gamma**2),proper=4,time=gamma*proper;
    add('A.5',`A moving clock has Lorentz factor $\\gamma=${fmt(gamma,4)}$. A proper time of ${proper} μs passes on it. What time interval is measured between these events in the observer’s frame?`,[n(time,'μs'),n(proper/gamma,'μs'),n(proper,'μs'),n(time*2,'μs')],`Time dilation gives $\\Delta t=\\gamma\\Delta t_0=${fmt(gamma,4)}(${proper})=${fmt(time)}$ μs. The proper time is measured by the clock present at both events.`);
    const gammaL=[1.25,2,2.5,4][i],L0=100,L=L0/gammaL;
    add('A.5',`A spacecraft’s proper length is ${L0} m. Its motion is parallel to its length and its Lorentz factor relative to an observer is ${gammaL}. What length does that observer measure?`,[n(L,'m'),n(L0*gammaL,'m'),n(L0,'m'),n(L/2,'m')],`Longitudinal length contraction gives $L=L_0/\\gamma=${L0}/${gammaL}=${L}$ m.`);
    const b=[0.6,0.8,0.5,0.9][i],g=1/Math.sqrt(1-b*b);
    add('A.5',`What is the Lorentz factor for relative speed $v=${b}c$?`,[fmt(g),fmt(1/(1-b*b)),fmt(Math.sqrt(1-b*b)),fmt(1/(1-b))],`$\\gamma=1/\\sqrt{1-v^2/c^2}=1/\\sqrt{1-${b}^2}=${fmt(g)}$. The square root is essential.`);
    const uv=[0.8,0.7,0.9,0.6][i],vv=0.5,up=(uv-vv)/(1-uv*vv);
    add('A.5',`In frame S, an object moves at $u=${uv}c$ along +x. Frame S′ moves at $v=${vv}c$ along +x relative to S. What is the object’s velocity in S′?`,[`${fmt(up)}c`,`${fmt(uv-vv)}c`,`${fmt(uv+vv)}c`,`${fmt((uv-vv)/(1+uv*vv))}c`],`Relativistic transformation gives $u'=(u-v)/(1-uv/c^2)=[(${uv}-${vv})/(1-${uv}(${vv}))]c=${fmt(up)}c$.`,'Challenge');
    const ct=5+2*i,x=3+2*i,interval=ct*ct-x*x;
    add('A.5',`Two events have $c\\Delta t=${ct}$ m and $\\Delta x=${x}$ m in an inertial frame. What is their squared space–time interval?`,[n(interval,'m²'),n(ct*ct+x*x,'m²'),n(ct-x,'m²'),n(-interval,'m²')],`Use the time-minus-space convention in the booklet: $(\\Delta s)^2=(c\\Delta t)^2-(\\Delta x)^2=${ct}^2-${x}^2=${interval}$ m².`);
  }

  [
    ['What does internal energy include in a molecular model?', ['Random molecular kinetic energy and intermolecular potential energy', 'Only the kinetic energy of the object’s centre of mass', 'Only gravitational potential energy', 'Only energy transferred as heat in the past'], 'Internal energy is microscopic: random particle motion plus potential energy associated with particle interactions. Bulk motion is a separate energy store.'],
    ['Which quantity determines the direction of net spontaneous thermal energy transfer?', ['Temperature difference', 'Total internal energy alone', 'Mass difference alone', 'Volume difference alone'], 'Net thermal energy transfer is from higher to lower temperature. A large cold object can have more internal energy than a small hot one.'],
    ['A substance melts at constant pressure and temperature. What happens to its internal energy as it absorbs latent heat?', ['It increases, mainly through molecular potential energy.', 'It stays constant because temperature is constant.', 'Its random kinetic energy doubles.', 'Its temperature must decrease.'], 'During a phase change, absorbed energy changes particle separation and arrangement without changing mean kinetic energy associated with temperature.'],
    ['A temperature rises by 20°C. What is the change in kelvin?', ['20 K', '293 K', '253 K', '20/273 K'], 'Kelvin and Celsius increments have the same size. The 273 offset applies to absolute readings, not temperature differences.'],
    ['Which thermal transfer mechanism can occur through a vacuum?', ['Radiation', 'Conduction by molecules', 'Convection', 'Bulk movement of fluid'], 'Thermal radiation consists of electromagnetic waves, which can propagate in a vacuum. Conduction and convection require matter.'],
    ['Why does a fluid heated from below often develop convection currents?', ['The warmed fluid becomes less dense and rises under buoyancy.', 'Heat is a substance that always rises.', 'The warmed fluid necessarily becomes denser.', 'Radiation pushes all fluid upward.'], 'Thermal expansion can reduce the density of a heated fluid. Buoyant forces then drive bulk motion, transferring energy by convection.'],
    ['For conduction through a uniform slab, what happens to the transfer rate if slab thickness doubles while all other factors remain fixed?', ['It halves.', 'It doubles.', 'It quadruples.', 'It is unchanged.'], '$\\Delta Q/\\Delta t=kA\\Delta T/\\Delta x$. At fixed material, area and temperature difference, the rate is inversely proportional to thickness.'],
    ['An ideal black body is at twice its original absolute temperature with the same surface area. How does its luminosity change?', ['It increases by a factor of 16.', 'It doubles.', 'It quadruples.', 'It decreases by a factor of 2.'], 'Stefan–Boltzmann law gives $L=\\sigma AT^4$. Doubling absolute temperature multiplies luminosity by $2^4=16$.'],
    ['An observer moves to twice the distance from an isotropically radiating star. How does apparent brightness change?', ['It becomes one quarter.', 'It halves.', 'It doubles.', 'It is unchanged.'], 'The same luminosity spreads over a sphere of area $4\\pi d^2$. Thus brightness varies as $1/d^2$.'],
    ['A black-body spectrum shifts to a shorter peak wavelength. What does this indicate?', ['A higher temperature', 'A lower temperature', 'A lower speed of light', 'A larger distance alone'], 'Wien’s law is $\\lambda_{max}T=constant$. A smaller peak wavelength therefore corresponds to a larger absolute temperature.'],
    ['Two bodies have equal temperatures but different masses. What can be concluded about their mean particle kinetic energies for the same ideal monatomic gas?', ['They have equal mean translational kinetic energy per particle.', 'The more massive body has a higher mean energy per particle.', 'The smaller body has zero internal energy.', 'Their total internal energies must be equal.'], 'For an ideal monatomic gas, mean translational kinetic energy is $3k_BT/2$, depending on temperature rather than total sample mass.'],
    ['What is specific heat capacity?', ['Energy needed to raise 1 kg of a substance by 1 K without a phase change', 'Energy needed to melt any amount of substance', 'Energy emitted per second per square metre', 'The temperature at which a substance boils'], 'Specific heat capacity is defined by $c=Q/(m\\Delta T)$, with SI unit J kg⁻¹ K⁻¹.'],
    ['What is specific latent heat?', ['Energy transferred per unit mass during a phase change at constant temperature', 'Energy transferred per unit temperature rise', 'The random kinetic energy per particle', 'The energy emitted per unit time'], 'Specific latent heat is $L=Q/m$ for a phase change, with SI unit J kg⁻¹. Temperature stays constant during an equilibrium phase change.'],
    ['Evaporation can cool the liquid that remains. Why?', ['Escaping molecules tend to have above-average kinetic energy.', 'All molecules leave with exactly the average kinetic energy.', 'The liquid’s molecular mass decreases.', 'Evaporation can occur only at the boiling point.'], 'The higher-energy part of the molecular distribution preferentially escapes. The remaining molecules can then have a lower mean kinetic energy and temperature.'],
    ['What is the SI unit of thermal conductivity?', ['W m⁻¹ K⁻¹', 'J kg⁻¹ K⁻¹', 'W m⁻² K⁻⁴', 'J K⁻¹'], 'From $P=kA\\Delta T/\\Delta x$, $k=P\\Delta x/(A\\Delta T)$, giving W m⁻¹ K⁻¹.'],
    ['A sphere’s radius has 2% uncertainty. Its surface area is calculated as $A=4\\pi r^2$. What is the percentage uncertainty in area?', ['4%', '2%', '8%', '1%'], 'The constants are exact for this calculation. The exponent doubles the radius’s fractional uncertainty: $\\Delta A/A=2\\Delta r/r=4\\%$.']
  ].forEach(x=>add('B.1',...x));
  for(let i=0;i<4;i++) {
    const mass=0.2+0.1*i,c=4000,dT=10,Q=mass*c*dT;
    add('B.1',`A ${fmt(mass)} kg sample with specific heat capacity ${c} J kg⁻¹ K⁻¹ is heated by ${dT} K without a phase change. What energy does it absorb?`,[n(Q,'J'),n(Q/10,'J'),n(Q*2,'J'),n(Q/2,'J')],`$Q=mc\\Delta T=${fmt(mass)}(${c})(${dT})=${fmt(Q)}$ J, assuming no energy losses.`);
    const m=0.1*(i+1),latent=3.3e5,heat=m*latent;
    add('B.1',`A mass ${fmt(m)} kg of ice at its melting point melts completely. Its specific latent heat of fusion is $3.3\\times10^5$ J kg⁻¹. How much energy is required?`,[n(heat,'J'),n(heat/10,'J'),n(heat*10,'J'),n(heat/2,'J')],`At the melting point use $Q=mL=${fmt(m)}(3.3\\times10^5)=${fmt(heat)}$ J. No separate temperature-rise term is needed.`);
    const k=0.2+0.1*i,A=2,delta=10,thick=0.1,rate=k*A*delta/thick;
    add('B.1',`A slab has thermal conductivity ${fmt(k)} W m⁻¹ K⁻¹, area ${A} m² and thickness ${thick} m. Its faces differ by ${delta} K. What is the steady conduction rate?`,[n(rate,'W'),n(rate/10,'W'),n(rate*2,'W'),n(rate/2,'W')],`$P=kA\\Delta T/\\Delta x=${fmt(k)}(2)(10)/0.1=${fmt(rate)}$ W.`);
    const temp=3000+1000*i,lambda=2.9e-3/temp*1e9;
    add('B.1',`A star is approximated as a black body at ${temp} K. Using Wien’s constant $2.9\\times10^{-3}$ m K, what is its peak wavelength?`,[n(lambda,'nm'),n(lambda*10,'nm'),n(lambda/10,'nm'),n(lambda*2,'nm')],`$\\lambda_{max}=2.9\\times10^{-3}/T=${fmt(lambda/1000)}\\times10^{-6}$ m, or ${fmt(lambda)} nm.`);
    const distance=2+i,factor=distance*distance;
    add('B.1',`An observer’s distance from a star is multiplied by ${distance}. The star’s luminosity is unchanged. By what factor is its apparent brightness multiplied?`,[fmt(1/factor),fmt(1/distance),String(distance),String(factor)],`Brightness follows $b=L/(4\\pi d^2)$. Multiplying distance by ${distance} multiplies brightness by $1/${distance}^2=${fmt(1/factor)}$.`);
    const mkg=3+i,volume=0.002,density=mkg/volume;
    add('B.1',`A solid of mass ${mkg} kg occupies $2.0\\times10^{-3}$ m³. What is its density?`,[n(density,'kg m⁻³'),n(density/10,'kg m⁻³'),n(density*10,'kg m⁻³'),n(density/2,'kg m⁻³')],`$\\rho=m/V=${mkg}/0.002=${density}$ kg m⁻³.`,'Foundation');
  }

  [
    ['What is a planet’s albedo?', ['The fraction of incident radiant power scattered back', 'The fraction of outgoing infrared radiation absorbed by its surface', 'The planet’s surface temperature', 'The total radiation emitted per second'], 'Albedo is scattered power divided by incident power. It is a dimensionless fraction between zero and one.'],
    ['What is the emissivity of an ideal black body?', ['1', '0', '1/2', 'It depends only on the body’s mass.'], 'An ideal black body emits the maximum thermal radiation possible at its temperature, so its emissivity is one.'],
    ['Why is the solar power intercepted by a spherical planet proportional to $\\pi R^2$ rather than $4\\pi R^2$?', ['The planet presents a circular projected area to parallel sunlight.', 'Only one quarter of the planet has mass.', 'The planet radiates only from a flat disk.', 'Sunlight reaches only the equator.'], 'A sphere’s shadow has area $\\pi R^2$. Its whole surface area, $4\\pi R^2$, is relevant when averaging the intercepted power globally.'],
    ['Why is the globally averaged incident solar intensity $S/4$ for a spherical planet?', ['Intercepted power $S\\pi R^2$ is averaged over $4\\pi R^2$.', 'Solar intensity is reduced by a quarter at every atmospheric boundary.', 'The solar constant already excludes reflected radiation.', 'Only infrared radiation reaches the night side.'], 'The factor of four comes from the ratio of circular projected area to spherical surface area. Albedo is a separate correction.'],
    ['Which set contains three important greenhouse gases?', ['Carbon dioxide, methane and water vapour', 'Oxygen, nitrogen and argon', 'Helium, neon and oxygen', 'Hydrogen, oxygen and argon'], 'CO₂, CH₄ and H₂O absorb in relevant infrared bands. Nitrogen and oxygen are not major absorbers of terrestrial infrared in this model.'],
    ['How do greenhouse gases interact with much of the outgoing terrestrial infrared radiation?', ['They absorb at allowed molecular transitions and emit radiation in all directions.', 'They reflect every infrared photon like a perfect mirror.', 'They absorb all sunlight and emit no radiation.', 'They turn radiation into matter permanently.'], 'Infrared absorption excites molecular rotational or vibrational energy levels. Subsequent emission and energy exchange redistribute energy, including downward radiation.'],
    ['Which change, considered by itself, increases a planet’s absorbed solar power?', ['A decrease in albedo', 'An increase in albedo', 'A decrease in the solar constant', 'An increase in distance from its star'], 'Absorbed solar power is $(1-a)S\\pi R^2$. Reducing albedo $a$ increases the fraction absorbed.'],
    ['In a simple one-temperature radiative equilibrium model with fixed albedo and emissivity, how does equilibrium temperature depend on solar constant?', ['$T\\propto S^{1/4}$', '$T\\propto S$', '$T\\propto S^4$', '$T\\propto 1/S$'], 'Energy balance gives $(1-a)S/4=\\varepsilon\\sigma T^4$. With the other factors fixed, $T$ is proportional to the fourth root of $S$.'],
    ['In a simple radiative equilibrium model, what happens if albedo increases while all other parameters remain fixed?', ['The equilibrium temperature decreases.', 'The equilibrium temperature increases.', 'The absorbed solar intensity increases.', 'The outgoing equilibrium power exceeds the incoming power forever.'], 'A higher albedo reflects a larger fraction of sunlight. The reduced absorbed power is balanced by a lower equilibrium temperature.'],
    ['What is meant by the enhanced greenhouse effect?', ['An increase in the greenhouse effect associated with human activities', 'The complete absence of natural greenhouse gases', 'The reflection of all sunlight by clouds', 'The warming caused only by Earth’s internal radioactivity'], 'Human activities, including fossil-fuel combustion, alter greenhouse-gas concentrations and increase the greenhouse effect beyond its natural level.'],
    ['Why can Earth’s albedo vary from day to day?', ['Cloud cover and surface conditions can change.', 'The Stefan–Boltzmann constant changes daily.', 'The vacuum speed of light changes daily.', 'Earth’s radius changes by a large factor daily.'], 'Clouds, ice, vegetation and other surface properties affect reflected sunlight. Cloud changes are a major source of daily albedo variability.'],
    ['Which statement about a surface with emissivity 0.6 at temperature $T$ is correct in the grey-body model?', ['It emits 60% of the black-body power per unit area at the same temperature.', 'Its temperature is 60% of a black body’s temperature.', 'It reflects exactly 60% of all incoming sunlight in every situation.', 'It emits no infrared radiation.'], 'Emissivity compares thermal emission with $\\sigma T^4$ at the same temperature. It is not a direct temperature ratio or a universal solar albedo.'],
    ['A planet is in steady radiative equilibrium. What is true of its total absorbed and emitted radiant powers?', ['They are equal.', 'Absorbed power is always larger.', 'Emitted power is zero.', 'Their ratio equals the planet’s radius.'], 'Steady temperature requires no net energy accumulation, so the total absorbed radiant power equals the total emitted radiant power.'],
    ['A planet temporarily absorbs more power than it emits. What initially happens?', ['Its internal energy tends to increase.', 'Energy conservation fails.', 'Its temperature must instantly fall.', 'Its albedo must become exactly one.'], 'A positive net energy input increases the planet-system’s stored energy. Warming or other energy storage can follow until the balance changes.'],
    ['Why does a greenhouse gas absorb some infrared wavelengths more strongly than others?', ['Molecular energy transitions have particular allowed energy differences.', 'Every molecule absorbs every wavelength equally.', 'Infrared photons have no energy.', 'The gas must be opaque to visible light.'], 'A photon can excite a molecular transition when its energy matches an allowed level difference. This produces wavelength-dependent absorption bands.'],
    ['What does the solar constant specify?', ['Solar radiant power per unit area normal to the rays at a specified orbital distance', 'The total power emitted by Earth', 'The radiation reflected by all clouds', 'The same irradiance at every distance from the Sun'], 'Solar irradiance is measured on a surface perpendicular to incoming rays at a specified distance, usually Earth’s mean orbital distance for the quoted solar constant.'],
    ['Why is the natural greenhouse effect important for Earth’s surface temperature?', ['It reduces the rate at which the surface loses energy directly to space.', 'It creates energy without any solar input.', 'It stops all outgoing radiation permanently.', 'It makes Earth’s albedo exactly zero.'], 'Atmospheric absorption and emission affect the surface energy balance. A warmer surface is compatible with the planetary outgoing radiation still balancing absorbed sunlight at equilibrium.'],
    ['A surface receives an infrared photon emitted downward by the atmosphere. What can happen if it absorbs the photon?', ['Its internal energy increases.', 'The photon’s energy is destroyed.', 'Its temperature must decrease.', 'Its albedo necessarily becomes one.'], 'Absorption transfers the photon’s energy into the surface. Individual exchanges can occur in either direction while net spontaneous heat transfer remains from hot to cold.'],
    ['Which process is a primary source of the human-driven increase in atmospheric carbon dioxide?', ['Combustion of fossil fuels', 'Conservation of angular momentum', 'Reflection of sunlight by snow', 'Elastic scattering by an ideal mirror'], 'Burning carbon-rich fossil fuels transfers carbon to the atmosphere as CO₂ and contributes to the enhanced greenhouse effect.'],
    ['A simple equilibrium model ignores atmospheric layers, ocean circulation and clouds changing with temperature. What is a suitable interpretation?', ['It is an approximation whose omitted feedbacks can affect the prediction.', 'It must reproduce all regional weather exactly.', 'It violates conservation of energy automatically.', 'Its temperature calculation needs no assumptions.'], 'Simple models can isolate the energy-balance mechanism, but their numerical predictions depend on assumptions and omitted feedbacks.'],
    ['A planet’s orbit moves outward from its star. Its albedo and emissivity stay fixed. What tends to happen in a simple equilibrium model?', ['Its equilibrium temperature decreases.', 'Its equilibrium temperature increases.', 'Its solar irradiance increases.', 'Its outgoing power is forced to remain larger than absorbed power forever.'], 'Stellar irradiance falls with inverse-square distance. Less absorbed power is balanced at a lower equilibrium temperature.'],
    ['A planet’s radius doubles while solar constant, albedo and emissivity stay fixed. In a uniform-temperature equilibrium model, what happens to temperature?', ['It is unchanged.', 'It doubles.', 'It halves.', 'It quadruples.'], 'Both intercepted solar power and emitted thermal power scale with $R^2$. Radius therefore cancels from the equilibrium-temperature equation.'],
    ['How is an increase in water vapour often linked to warming?', ['Warmer conditions can support more water vapour, strengthening infrared absorption.', 'Water vapour cannot absorb infrared radiation.', 'Water vapour always makes albedo zero.', 'Water vapour removes all atmospheric energy permanently.'], 'Water vapour is a greenhouse gas. Its concentration can rise with warming, creating a positive feedback under suitable conditions.'],
    ['Why should Celsius temperatures not be inserted directly into $P=\\varepsilon\\sigma AT^4$?', ['The radiation law requires absolute temperature in kelvin.', 'The law requires temperature in degrees Fahrenheit.', 'The law applies only at 0°C.', 'Temperature has no effect on radiation.'], 'Thermal radiation depends on absolute temperature. The Celsius scale has an arbitrary offset, so its readings cannot be raised to the fourth power in this law.']
  ].forEach(x=>add('B.2',...x));
  for(let i=0;i<4;i++) {
    const S=1000+200*i,a=0.2+0.1*i,absorbed=(1-a)*S/4;
    add('B.2',`A spherical planet has solar constant ${S} W m⁻² and albedo ${fmt(a)}. What is the globally averaged absorbed solar intensity?`,[n(absorbed,'W m⁻²'),n((1-a)*S,'W m⁻²'),n(S,'W m⁻²'),n(S/4,'W m⁻²')],`Average the intercepted solar power over the sphere and remove the reflected fraction: $I_{abs}=(1-a)S/4=(1-${fmt(a)})(${S})/4=${fmt(absorbed)}$ W m⁻².`);
    const eps=0.4+0.1*i,black=400,power=eps*black;
    add('B.2',`An ideal black body at temperature $T$ emits ${black} W m⁻². A grey surface at the same temperature has emissivity ${fmt(eps)}. What does it emit?`,[n(power,'W m⁻²'),n(black,'W m⁻²'),n(black*2,'W m⁻²'),n(power/2,'W m⁻²')],`By definition $I=\\varepsilon\\sigma T^4$. Here $\\sigma T^4=${black}$ W m⁻², so $I=${fmt(eps)}(${black})=${fmt(power)}$ W m⁻².`);
    const incident=500+100*i,reflected=0.3*incident;
    add('B.2',`A surface receives ${incident} W of radiation and scatters ${reflected} W back. What is its albedo?`,['0.30','0.70','3.33','0.15'],`Albedo is reflected (scattered) power divided by incident power: $a=${reflected}/${incident}=0.30$. The absorbed fraction is 0.70.`,'Foundation');
    const mult=[2,3,4,5][i],ratio=Math.pow(mult,0.25);
    add('B.2',`In a simple planetary equilibrium model, solar constant increases by a factor of ${mult}, with albedo and emissivity fixed. By what factor does equilibrium absolute temperature increase?`,[fmt(ratio),String(mult),fmt(Math.sqrt(mult)),fmt(1/ratio)],`Since $T^4\\propto S$, the temperature factor is $${mult}^{1/4}=${fmt(ratio)}$. The temperature response is weaker than the change in solar intensity.`);
  }

  [
    ['What produces the pressure of an ideal gas on its container walls?', ['Momentum transfer during molecular collisions with the walls', 'A continuous attractive force between all molecules and the walls', 'The weight of individual molecules only', 'Conversion of mass into heat at the walls'], 'Gas particles change momentum when they collide with the walls. The rate of momentum transfer gives the force, and force per area is pressure.'],
    ['Which assumption belongs to the ideal-gas kinetic model?', ['Molecular volume is negligible compared with container volume.', 'Molecules remain at rest between collisions.', 'All collisions are perfectly inelastic.', 'Intermolecular potential energy dominates.'], 'The ideal-gas model treats molecules as having negligible volume, negligible forces except during collisions, and elastic collisions.'],
    ['Under which conditions is a real gas usually closest to ideal behaviour?', ['Low pressure and high temperature', 'High pressure and low temperature', 'Near condensation at high density', 'At any pressure if its volume is exactly 1 m³'], 'Low density makes molecular size and intermolecular forces relatively less important; higher temperature also reduces the relative importance of attractive interactions.'],
    ['A fixed amount of ideal gas is held at constant temperature. How are pressure and volume related?', ['$P\\propto1/V$', '$P\\propto V$', '$P\\propto V^2$', '$P$ is independent of $V$.'], 'The ideal-gas law becomes $PV=constant$ at constant amount and temperature. Thus pressure is inversely proportional to volume.'],
    ['For a fixed amount of gas at constant volume, which temperature scale makes pressure proportional to temperature?', ['Kelvin', 'Celsius', 'Fahrenheit', 'Any scale with an arbitrary zero'], '$P=nRT/V$ requires absolute temperature. Pressure is proportional to kelvin temperature, not to Celsius readings.'],
    ['Two ideal gases at the same temperature have different molecular masses. What is equal for their molecules?', ['Mean translational kinetic energy', 'Root-mean-square speed', 'Momentum of every molecule', 'Mass of every molecule'], '$\\overline{E_k}=3k_BT/2$ is the same at equal temperature. Lighter molecules have greater mean-square speeds.'],
    ['At fixed temperature, how does root-mean-square speed depend on molecular mass $m$?', ['$v_{rms}\\propto1/\\sqrt{m}$', '$v_{rms}\\propto m$', '$v_{rms}\\propto1/m$', '$v_{rms}$ is independent of $m$.'], 'Combining $m\\overline{v^2}/2=3k_BT/2$ gives $v_{rms}=\\sqrt{3k_BT/m}$.'],
    ['For an ideal monatomic gas, on which quantity does internal energy depend when the amount of gas is fixed?', ['Absolute temperature', 'Pressure alone, independently of temperature', 'Container shape', 'Intermolecular potential energy'], '$U=3nRT/2$ for an ideal monatomic gas. Its internal energy is entirely random translational kinetic energy in this model.'],
    ['In $P=\\rho\\overline{v^2}/3$, what does $\\overline{v^2}$ represent?', ['The mean of the squared molecular speeds', 'The square of the average velocity vector', 'The speed of the container', 'The average acceleration'], 'An equilibrium gas has zero average velocity vector but non-zero mean-square speed. The latter determines pressure.'],
    ['A fixed amount of ideal gas doubles in absolute temperature at constant volume. What happens to pressure?', ['It doubles.', 'It halves.', 'It quadruples.', 'It is unchanged.'], 'At fixed $n$ and $V$, the ideal-gas law gives $P\\propto T$. Doubling kelvin temperature doubles pressure.'],
    ['A fixed amount of ideal gas expands at constant pressure. What happens to volume if absolute temperature doubles?', ['It doubles.', 'It halves.', 'It quadruples.', 'It is unchanged.'], 'At fixed pressure, $V=nRT/P$ is directly proportional to kelvin temperature.'],
    ['Which is a correct relationship between gas constant $R$, Avogadro constant $N_A$ and Boltzmann constant $k_B$?', ['$R=N_Ak_B$', '$R=k_B/N_A$', '$R=N_A/k_B$', '$R=N_A+k_B$'], 'The forms $PV=nRT$ and $PV=Nk_BT$ agree because $N=nN_A$ and $R=N_Ak_B$.'],
    ['At constant temperature, the number of gas molecules and container volume both double. What happens to pressure?', ['It is unchanged.', 'It doubles.', 'It halves.', 'It quadruples.'], '$P=Nk_BT/V$. Doubling both $N$ and $V$ leaves the number density and pressure unchanged.'],
    ['Why does an ideal monatomic gas have no intermolecular potential-energy contribution to its internal energy?', ['Intermolecular forces are neglected except during collisions.', 'Its molecules have zero kinetic energy.', 'Its temperature is always zero.', 'Its pressure is always zero.'], 'The idealization neglects sustained intermolecular forces, so the internal energy is treated as the total random translational kinetic energy.'],
    ['A pressure–volume diagram shows an isothermal ideal-gas process. What shape does the curve have?', ['A decreasing hyperbola', 'A horizontal straight line', 'A vertical straight line', 'A straight line through the origin'], 'At constant temperature and amount of gas, $P=nRT/V$. This inverse relation is a rectangular hyperbola.'],
    ['A gas sample is heated from 27°C to 127°C at constant volume. Approximately what is $P_2/P_1$?', ['4/3', '127/27', '3/4', '100'], 'Convert to approximately 300 K and 400 K. At constant volume $P_2/P_1=T_2/T_1=400/300=4/3$.']
  ].forEach(x=>add('B.3',...x));
  for(let i=0;i<4;i++) {
    const pressure=1e5,volume=0.01+0.005*i,T=300,moles=pressure*volume/(8.31*T);
    add('B.3',`An ideal gas occupies ${fmt(volume)} m³ at $1.0\\times10^5$ Pa and ${T} K. Use $R=8.31$ J mol⁻¹ K⁻¹. What is the amount of gas?`,[n(moles,'mol'),n(moles*10,'mol'),n(moles/10,'mol'),n(moles*2,'mol')],`Rearrange $PV=nRT$: $n=PV/(RT)=10^5(${fmt(volume)})/[8.31(300)]=${fmt(moles)}$ mol.`);
    const V1=2+i,V2=2*V1,P1=120+20*i;
    add('B.3',`A fixed amount of ideal gas at ${P1} kPa expands isothermally from ${V1} L to ${V2} L. What is the final pressure?`,[n(P1/2,'kPa'),n(P1*2,'kPa'),n(P1,'kPa'),n(P1/4,'kPa')],`For an isothermal change $P_1V_1=P_2V_2$. Since volume doubles, $P_2=${P1}/2=${P1/2}$ kPa. Litres may be used consistently in this ratio.`);
    const T1=200+50*i,T2=2*T1,P=80+10*i;
    add('B.3',`A sealed rigid gas container has pressure ${P} kPa at ${T1} K. What is the pressure at ${T2} K, assuming ideal-gas behaviour?`,[n(2*P,'kPa'),n(P/2,'kPa'),n(P,'kPa'),n(4*P,'kPa')],`At fixed volume and amount, $P_2/P_1=T_2/T_1=2$. Thus $P_2=${2*P}$ kPa.`);
    const mol=1+i,Tgas=300,U=1.5*mol*8.31*Tgas;
    add('B.3',`What is the internal energy of ${mol} mol of an ideal monatomic gas at ${Tgas} K? Use $R=8.31$ J mol⁻¹ K⁻¹.`,[n(U,'J'),n(mol*8.31*Tgas,'J'),n(U*2,'J'),n(U/2,'J')],`For a monatomic ideal gas, $U=3nRT/2=1.5(${mol})(8.31)(300)=${fmt(U)}$ J.`);
    const rho=0.6+0.2*i,rms=500,Pgas=rho*rms*rms/3;
    add('B.3',`A gas has density ${fmt(rho)} kg m⁻³ and root-mean-square molecular speed ${rms} m s⁻¹. What pressure does kinetic theory predict?`,[n(Pgas,'Pa'),n(3*Pgas,'Pa'),n(Pgas/3,'Pa'),n(rho*rms/3,'Pa')],`$P=\\rho v_{rms}^2/3=${fmt(rho)}(500)^2/3=${fmt(Pgas)}$ Pa. Use mean-square speed, not mean speed.`);
    const sampleMol=0.5+0.5*i,particles=sampleMol*6.02e23;
    add('B.3',`A sample contains ${sampleMol} mol of gas. Use $N_A=6.02\\times10^{23}$ mol⁻¹. How many molecules are present?`,[n(particles),n(particles/10),n(particles*10),n(particles/2)],`$N=nN_A=${sampleMol}(6.02\\times10^{23})=${fmt(particles/1e23)}\\times10^{23}$ molecules.`,'Foundation');
  }

  [
    ['Using the booklet convention $Q=\\Delta U+W$, what does positive $W$ mean?', ['Work done by the gas on its surroundings', 'Work done on the gas by its surroundings', 'Heat removed from the gas', 'An increase in internal energy only'], 'The IB convention takes work done by the system as positive and heat supplied to the system as positive. Thus $\\Delta U=Q-W$.'],
    ['What is a closed thermodynamic system?', ['A system that exchanges energy but not mass with its surroundings', 'A system that exchanges neither energy nor mass', 'A system with zero internal energy', 'A system that cannot do work'], 'A closed system has fixed mass but can exchange energy through heat or work. An isolated system exchanges neither mass nor energy.'],
    ['What is an isolated system?', ['A system that exchanges neither energy nor mass with its surroundings', 'A system held at constant temperature only', 'A system held at constant pressure only', 'Any gas in a container with a movable piston'], 'Isolation prevents both matter transfer and energy transfer across the system boundary.'],
    ['For an isochoric process, what is the work done by the gas?', ['Zero', '$P/V$', 'Equal to all heat transferred with zero internal-energy change', 'Always negative'], 'Work is the area under the pressure–volume curve, $W=\\int P\\,dV$. At fixed volume $dV=0$, so work is zero.'],
    ['For an isothermal process in an ideal monatomic gas, what is $\\Delta U$?', ['Zero', 'Equal to the work done with the same sign', 'Always positive', 'Always negative'], 'Ideal monatomic gas internal energy depends only on temperature. With no temperature change, $\\Delta U=0$ and $Q=W$.'],
    ['An ideal gas expands adiabatically and does positive work. What happens to its internal energy?', ['It decreases.', 'It increases.', 'It stays constant.', 'It becomes negative in every case.'], 'For an adiabatic process $Q=0$. The first law gives $\\Delta U=-W$, so positive work reduces internal energy and temperature.'],
    ['Which quantity is zero in an adiabatic process?', ['Heat transferred across the boundary', 'Work in every case', 'Temperature change in every case', 'Pressure in every case'], 'Adiabatic means $Q=0$, not constant temperature. Work can change the internal energy of an insulated gas.'],
    ['What does the area enclosed by a complete pressure–volume cycle represent?', ['Net work done in the cycle', 'Net change of internal energy', 'Final pressure', 'Total entropy of the gas'], 'Integrating $P\\,dV$ around a cycle gives its signed enclosed area. A cycle returns to its initial internal energy.'],
    ['For a clockwise cycle on a standard pressure–volume diagram, what is the sign of net work done by the gas?', ['Positive', 'Negative', 'Zero for every cycle', 'Undefined'], 'Expansion occurs at higher pressure than compression for a clockwise cycle. The positive expansion work exceeds the magnitude of negative compression work.'],
    ['A gas returns to its initial thermodynamic state after a cycle. What is its total internal-energy change?', ['Zero', 'Equal to the heat input alone', 'Equal to the net work alone', 'Necessarily positive'], 'Internal energy is a state function, so returning to the same state gives zero net change. Net heat supplied then equals net work done.'],
    ['Which statement expresses the second law for an isolated system?', ['Its total entropy cannot decrease.', 'Its energy must always increase.', 'Its entropy must remain zero.', 'Its temperature must always decrease.'], 'The entropy of an isolated system stays constant for an ideal reversible process and increases for an irreversible one.'],
    ['Can the entropy of a non-isolated system decrease?', ['Yes, if the surroundings gain at least enough entropy to compensate.', 'No, under any circumstances.', 'Yes, without any change outside the system.', 'Only if energy conservation is violated.'], 'Local entropy can decrease through energy exchange, but total entropy of system plus surroundings cannot decrease.'],
    ['How does entropy change when the number of accessible equally probable microstates increases?', ['It increases according to $S=k_B\\ln\\Omega$.', 'It decreases according to $S=k_B/\\Omega$.', 'It remains constant regardless of microstates.', 'It becomes negative in every case.'], 'Boltzmann’s relation connects entropy to the natural logarithm of the number of microstates. More accessible arrangements give greater entropy.'],
    ['A reversible engine operates between fixed hot and cold reservoirs. Which engine has the greatest possible efficiency?', ['A Carnot engine', 'Any engine with zero heat rejection', 'An engine whose efficiency exceeds 100%', 'A frictional engine running at the same temperatures'], 'The Carnot efficiency $1-T_c/T_h$ is the reversible upper limit for heat engines operating between the specified reservoir temperatures.'],
    ['Why must reservoir temperatures in the Carnot equation be in kelvin?', ['The equation uses ratios of absolute temperatures.', 'Celsius and kelvin ratios are always identical.', 'Heat engines operate only above 273°C.', 'The equation is independent of temperature.'], 'A temperature ratio is physically meaningful here only on an absolute scale. Adding a Celsius offset changes the ratio incorrectly.'],
    ['What is impossible for a cyclic heat engine that has only one thermal reservoir?', ['Converting all absorbed heat into net work without any other effect', 'Rejecting some heat while producing work between two reservoirs', 'Having zero net internal-energy change', 'Transferring energy by work'], 'The Kelvin statement of the second law rules out complete conversion of heat from a single reservoir into cyclic work without other changes.']
  ].forEach(x=>add('B.4',...x));
  for(let i=0;i<4;i++) {
    const heat=400+100*i,work=100+50*i,dU=heat-work;
    add('B.4',`A gas receives ${heat} J of heat and does ${work} J of work on its surroundings. What is its internal-energy change?`,[n(dU,'J'),n(heat+work,'J'),n(-dU,'J'),n(work-heat*2,'J')],`With heat supplied and work done by the gas positive, $\\Delta U=Q-W=${heat}-${work}=${dU}$ J.`);
    const P=1e5,Vchange=0.002+0.001*i,W=P*Vchange;
    add('B.4',`A gas expands at constant pressure $1.0\\times10^5$ Pa by ${fmt(Vchange)} m³. What work does it do?`,[n(W,'J'),n(-W,'J'),n(W/10,'J'),n(W*2,'J')],`For constant pressure, $W=P\\Delta V=10^5(${fmt(Vchange)})=${fmt(W)}$ J. Expansion gives positive work by the gas.`);
    const q=600+200*i,T=300,entropy=q/T;
    add('B.4',`A system reversibly absorbs ${q} J of heat at a constant temperature of ${T} K. What is its entropy change?`,[n(entropy,'J K⁻¹'),n(-entropy,'J K⁻¹'),n(entropy*2,'J K⁻¹'),n(entropy/2,'J K⁻¹')],`For reversible isothermal heat transfer, $\\Delta S=Q_{rev}/T=${q}/300=${fmt(entropy)}$ J K⁻¹.`);
    const hot=600+100*i,cold=300,eta=1-cold/hot;
    add('B.4',`A heat engine operates between reservoirs at ${hot} K and ${cold} K. What is its maximum possible efficiency?`,[`${fmt(100*eta)}%`,`${fmt(100*(1-(cold-273)/(hot-273)))}%`,'100%',`${fmt(50*eta)}%`],`The reversible Carnot limit is $\\eta=1-T_c/T_h=1-300/${hot}=${fmt(eta)}$, or ${fmt(100*eta)}%.`, 'Standard');
    const mol=1+i,dT=20,DU=1.5*mol*8.31*dT;
    add('B.4',`The temperature of ${mol} mol of an ideal monatomic gas increases by ${dT} K. Use $R=8.31$ J mol⁻¹ K⁻¹. What is its internal-energy increase?`,[n(DU,'J'),n(mol*8.31*dT,'J'),n(DU*2,'J'),n(DU/2,'J')],`$\\Delta U=3nR\\Delta T/2=1.5(${mol})(8.31)(20)=${fmt(DU)}$ J, independent of the path between the states.`);
    const ratio=2+i,pressureRatio=Math.pow(1/ratio,5/3);
    add('B.4',`An ideal monatomic gas expands reversibly and adiabatically so its volume is multiplied by ${ratio}. What is the ratio $P_2/P_1$?`,[fmt(pressureRatio),fmt(1/ratio),fmt(Math.pow(ratio,5/3)),fmt(Math.pow(1/ratio,2/3))],`For a reversible adiabatic change in a monatomic ideal gas $PV^{5/3}=constant$, so $P_2/P_1=(V_1/V_2)^{5/3}=(1/${ratio})^{5/3}=${fmt(pressureRatio)}$.`, 'Challenge');
  }

  [
    ['What is electric current?', ['Rate of flow of electric charge', 'Energy transferred per unit charge', 'Force per unit charge', 'Charge stored per unit potential difference'], 'Current is $I=\\Delta q/\\Delta t$, measured in amperes, where one ampere is one coulomb per second.'],
    ['What is electric potential difference?', ['Energy transferred per unit charge', 'Charge transferred per unit time', 'Force per unit mass', 'Energy transferred per unit time'], '$V=W/q$. One volt is one joule of energy transferred per coulomb of charge.'],
    ['Which statement is Ohm’s law for a conductor at fixed physical conditions?', ['Current is proportional to potential difference.', 'Resistance is proportional to current in every device.', 'Power is constant at every voltage.', 'Potential difference is independent of current.'], 'An ohmic conductor at constant temperature has a constant ratio $V/I$. Heating can change resistance and invalidate the fixed-condition approximation.'],
    ['How is an ideal ammeter connected to measure current through a resistor?', ['In series with the resistor', 'In parallel with the resistor', 'Across the power supply with no resistance', 'Disconnected from the circuit'], 'An ammeter must carry the same current as the component, so it is connected in series. An ideal ammeter has zero resistance.'],
    ['How is an ideal voltmeter connected to measure a resistor’s potential difference?', ['In parallel with the resistor', 'In series with the resistor', 'Only in place of the cell', 'Short-circuiting the resistor with a wire'], 'A voltmeter measures the potential difference between two terminals and is connected across them. An ideal voltmeter has infinite resistance.'],
    ['For resistors connected in series, which quantity is the same in each resistor?', ['Current', 'Potential difference in every case', 'Power in every case', 'Resistance'], 'There is a single path for charge, so the same current flows through every series component. Potential differences add.'],
    ['For resistors connected in parallel, which quantity is the same across every branch?', ['Potential difference', 'Current in every case', 'Resistance', 'Power in every case'], 'Each parallel branch connects to the same pair of nodes and therefore has the same potential difference. Branch currents add.'],
    ['A uniform wire’s length doubles and its cross-sectional area halves, with resistivity unchanged. What happens to resistance?', ['It becomes four times as large.', 'It doubles.', 'It halves.', 'It is unchanged.'], 'Using $R=\\rho L/A$, doubling $L$ and halving $A$ together multiply resistance by four.'],
    ['What is a cell’s emf?', ['Energy supplied by the cell per unit charge', 'The force acting on each electron', 'The current through its internal resistance', 'The potential difference lost only inside the cell'], 'Despite its historical name, emf is an energy-per-charge quantity measured in volts. Terminal voltage can be lower when current flows.'],
    ['A cell supplies current through an external resistor and has non-zero internal resistance. How does terminal voltage compare with emf?', ['Terminal voltage is smaller by $Ir$.', 'Terminal voltage is always larger by $Ir$.', 'They differ by $I/r$.', 'Terminal voltage is zero for every current.'], 'During discharge, part of the emf supplies the internal voltage drop: $V=\\varepsilon-Ir$.'],
    ['What usually happens to the resistance of an NTC thermistor when its temperature increases?', ['It decreases.', 'It increases.', 'It becomes exactly zero immediately.', 'It is unaffected by temperature.'], 'For a negative-temperature-coefficient thermistor, an increase in temperature increases available charge carriers and decreases resistance over its operating range.'],
    ['What usually happens to an LDR’s resistance when light intensity increases?', ['It decreases.', 'It increases.', 'It becomes infinite.', 'It stays constant for every material.'], 'Illumination generates more mobile charge carriers in a light-dependent resistor, lowering its resistance.'],
    ['Why does a filament lamp’s current–voltage graph bend as voltage increases?', ['The filament heats and its resistance increases.', 'Its resistance becomes negative.', 'Charge stops being conserved.', 'Its filament temperature remains exactly constant.'], 'A hotter metallic filament has greater resistance. Consequently current rises less than proportionally as potential difference increases.'],
    ['Two identical resistors are first connected in series and then in parallel to the same ideal voltage source. How does total power in parallel compare with total power in series?', ['It is four times as large.', 'It is twice as large.', 'It is one half as large.', 'It is unchanged.'], 'The total resistance changes from $2R$ to $R/2$. At fixed voltage $P=V^2/R_{eq}$, so power increases by a factor of four.'],
    ['Which microscopic explanation describes electrical resistance in a metal?', ['Charge carriers transfer energy in interactions with the lattice.', 'Electrons are permanently consumed by every resistor.', 'Positive lattice ions carry the entire current along the wire.', 'Potential difference directly destroys charge.'], 'Charge carriers gain energy from the electric field and transfer it through interactions with the lattice, increasing internal energy. Charge is conserved.'],
    ['A wire resistance is calculated from $R=\\rho L/A$. The percentage uncertainties in resistivity, length and area are 2%, 1% and 3%. What is the percentage uncertainty in resistance?', ['6%', '0%', '3%', '2%'], 'For products and quotients, maximum fractional uncertainties add: $2\\%+1\\%+3\\%=6\\%$.']
  ].forEach(x=>add('B.5',...x));
  for(let i=0;i<4;i++) {
    const charge=12+6*i,time=3,current=charge/time;
    add('B.5',`${charge} C of charge passes a point in a circuit in ${time} s. What is the average current?`,[n(current,'A'),n(charge*time,'A'),n(time/charge,'A'),n(current/2,'A')],`$I=\\Delta q/\\Delta t=${charge}/3=${current}$ A.`,'Foundation');
    const voltage=12+6*i,resistance=3,I=voltage/resistance;
    add('B.5',`A ${resistance} Ω resistor has ${voltage} V across it. What current flows through it?`,[n(I,'A'),n(voltage*resistance,'A'),n(resistance/voltage,'A'),n(I/2,'A')],`From $R=V/I$, $I=V/R=${voltage}/3=${I}$ A.`,'Foundation');
    const R1=2+i,R2=2*R1,Rp=R1*R2/(R1+R2);
    add('B.5',`Resistors of ${R1} Ω and ${R2} Ω are connected in parallel. What is their equivalent resistance?`,[n(Rp,'Ω'),n(R1+R2,'Ω'),n((R1+R2)/2,'Ω'),n(R2,'Ω')],`$1/R_p=1/R_1+1/R_2$, so $R_p=R_1R_2/(R_1+R_2)=${R1}(${R2})/${R1+R2}=${fmt(Rp)}$ Ω. It is less than the smaller resistor.`);
    const Icur=2+i,R=4,pow=Icur*Icur*R;
    add('B.5',`A ${R} Ω resistor carries a steady current of ${Icur} A. What power is dissipated?`,[n(pow,'W'),n(pow*0.75,'W'),n(pow/4,'W'),n(pow*2,'W')],`$P=I^2R=${Icur}^2(4)=${pow}$ W. The square of current is required.`);
    const emf=12+2*i,r=1,Rload=5,Iload=emf/(r+Rload),terminal=Iload*Rload;
    add('B.5',`A cell has emf ${emf} V and internal resistance ${r} Ω. It supplies a ${Rload} Ω external resistor. What is its terminal voltage?`,[n(terminal,'V'),n(emf,'V'),n(Iload*r,'V'),n(terminal/2,'V')],`The current is $I=\\varepsilon/(R+r)=${emf}/6=${fmt(Iload)}$ A. Terminal voltage is $IR=${fmt(Iload)}(5)=${fmt(terminal)}$ V.`);
    const rho=2e-8,L=2+i,A=1e-6,Rwire=rho*L/A;
    add('B.5',`A wire has resistivity $2.0\\times10^{-8}$ Ω m, length ${L} m and cross-sectional area $1.0\\times10^{-6}$ m². What is its resistance?`,[n(Rwire,'Ω'),n(Rwire*10,'Ω'),n(Rwire/10,'Ω'),n(Rwire*2,'Ω')],`$R=\\rho L/A=(2.0\\times10^{-8})(${L})/(1.0\\times10^{-6})=${fmt(Rwire)}$ Ω.`);
  }
  // Additional multi-step and representation questions extend coverage beyond the numerical sets.
  add('A.1', 'A cyclist travels 120 m at 6 m s⁻¹ and then 120 m at 4 m s⁻¹. What is the average speed for the whole trip?', ['4.8 m s⁻¹', '5.0 m s⁻¹', '10 m s⁻¹', '2.4 m s⁻¹'], 'Total time is $120/6+120/4=50$ s. Average speed is total distance divided by total time: $240/50=4.8$ m s⁻¹. Averaging the two speeds arithmetically would require equal times.', 'Challenge');
  add('A.1', 'A projectile is launched at 20 m s⁻¹, 30° above the horizontal. It lands at its launch height. Use $g=10$ m s⁻² and neglect drag. What is its time of flight?', ['2.0 s', '1.0 s', '4.0 s', '3.46 s'], 'The initial vertical speed is $20\\sin30^\\circ=10$ m s⁻¹. Time to the highest point is $u_y/g=1$ s, and the symmetric flight lasts 2 s.', 'Standard');
  add('A.1', 'An object starts at $x=0$ and moves at +4 m s⁻¹ for 3 s, then at −2 m s⁻¹ for 4 s. What is its average velocity?', ['0.571 m s⁻¹', '2.86 m s⁻¹', '1.0 m s⁻¹', '4.0 m s⁻¹'], 'Signed displacement is $4(3)-2(4)=4$ m over 7 s. Average velocity is $4/7=0.571$ m s⁻¹. Total distance divided by time would give average speed.', 'Challenge');
  add('A.1', 'A ball is thrown upward from a platform. At a later instant it is below the release point and still moving downward. Taking upward as positive and neglecting drag, which signs describe displacement, velocity and acceleration?', ['All three are negative.', 'Displacement negative, velocity negative, acceleration positive', 'Displacement positive, velocity negative, acceleration negative', 'Displacement negative, velocity positive, acceleration zero'], 'The ball is below the initial position, moves downward and accelerates under downward gravity. All are negative with the specified upward-positive convention.', 'Standard');

  add('A.2', 'A 1 kg puck initially moves at (6, 0) m s⁻¹ and hits a stationary 2 kg puck on a frictionless surface. The 1 kg puck leaves at (0, 2) m s⁻¹. What is the 2 kg puck’s final velocity? Components are (x, y).', ['(3, −1) m s⁻¹', '(6, −2) m s⁻¹', '(3, 1) m s⁻¹', '(0, −1) m s⁻¹'], 'Conserve momentum in each direction. Initially total momentum is (6, 0) kg m s⁻¹. Subtract final momentum (0, 2) of the first puck to get (6, −2); divide by 2 kg to obtain (3, −1) m s⁻¹.', 'Challenge', 'HL');
  add('A.2', 'A 1 kg particle’s velocity changes from (3, 0) m s⁻¹ to (0, 4) m s⁻¹. What is the magnitude of the resultant impulse?', ['5 N s', '1 N s', '7 N s', '25 N s'], 'Impulse is the vector change in momentum: $\\Delta p=(-3,4)$ kg m s⁻¹. Its magnitude is $\\sqrt{(-3)^2+4^2}=5$ N s.', 'Challenge', 'HL');
  add('A.2', 'A 0.5 kg mass moves in a vertical circle on a string. Its speed is 4 m s⁻¹ at the top, where the circle radius is 1 m. Use $g=10$ m s⁻². What is the string tension at the top?', ['3 N', '8 N', '13 N', '5 N'], 'At the top, both weight and tension act toward the centre: $T+mg=mv^2/r$. Thus $T=0.5(16)/1-0.5(10)=3$ N.', 'Challenge');
  add('A.2', 'Two small spheres have the same material density and fall at terminal speed in the same fluid in the Stokes regime. The second has twice the radius. What is the ratio of terminal speeds $v_2/v_1$?', ['4', '2', '8', '1/2'], 'At terminal speed, effective weight is balanced by Stokes drag. Effective weight scales as $r^3$ while drag scales as $rv$, so $v\\propto r^2$. Doubling radius multiplies terminal speed by four, provided both flows remain in the Stokes regime.', 'Challenge');

  add('A.3', 'A force parallel to motion increases linearly from 0 N to 10 N over a displacement of 4 m. What work does it do?', ['20 J', '40 J', '10 J', '2.5 J'], 'Work is the area under the force–displacement graph. The triangular area is $10(4)/2=20$ J; using the final force throughout would overestimate the work.', 'Standard');
  add('A.3', 'A 2 kg block starts from rest and slides down through a vertical height of 5 m. Friction transfers 20 J to internal energy. Use $g=10$ m s⁻². What is its final speed?', ['8.94 m s⁻¹', '10 m s⁻¹', '6.32 m s⁻¹', '4.47 m s⁻¹'], 'The gravitational energy decrease is $mgh=100$ J. Final kinetic energy is $100-20=80$ J, so $v=\\sqrt{2E_k/m}=\\sqrt{80}=8.94$ m s⁻¹.', 'Challenge');
  add('A.3', 'A 0.5 kg cart compresses a spring of constant 200 N m⁻¹ by 0.10 m before coming to rest. The track is horizontal and frictionless. What was its speed immediately before touching the spring?', ['2.0 m s⁻¹', '1.0 m s⁻¹', '4.0 m s⁻¹', '0.50 m s⁻¹'], 'Kinetic energy becomes spring energy: $mv^2/2=kx^2/2$. Thus $v=x\\sqrt{k/m}=0.10\\sqrt{200/0.5}=2.0$ m s⁻¹.', 'Challenge');
  add('A.3', 'A pump raises 5 kg of water each second through 8 m. It is 80% efficient. Use $g=10$ m s⁻². What input power is required?', ['500 W', '400 W', '320 W', '640 W'], 'Useful power is the gravitational energy gained per second: $P_{out}=\\dot mgh=5(10)(8)=400$ W. Input power is $P_{out}/\\eta=400/0.80=500$ W.', 'Challenge');

  add('A.4', 'A rotating disk of inertia $I$ at angular speed $\\omega$ is coupled to an identical disk initially at rest. External torque is negligible. What fraction of the initial rotational kinetic energy remains as rotational kinetic energy after they rotate together?', ['1/2', '1', '1/4', '2'], 'Angular momentum conservation gives $I\\omega=(2I)\\omega_f$, hence $\\omega_f=\\omega/2$. Final energy is $(2I)(\\omega/2)^2/2=I\\omega^2/4$, half the initial $I\\omega^2/2$.', 'Challenge');
  add('A.4', 'A solid cylinder rolls without slipping down through height $h$. It starts from rest and has $I=mr^2/2$. What is its final centre speed, neglecting energy losses?', ['$\\sqrt{4gh/3}$', '$\\sqrt{2gh}$', '$\\sqrt{gh}$', '$\\sqrt{2gh/3}$'], 'Energy conservation gives $mgh=mv^2/2+I\\omega^2/2$. Insert $I=mr^2/2$ and $\\omega=v/r$: $mgh=3mv^2/4$, so $v=\\sqrt{4gh/3}$.', 'Challenge');
  add('A.4', 'A wheel has angular momentum 12 kg m² s⁻¹. A constant opposing torque of 3 N m acts for 2 s. What is the final angular momentum, before any reversal?', ['6 kg m² s⁻¹', '18 kg m² s⁻¹', '9 kg m² s⁻¹', '24 kg m² s⁻¹'], 'The opposing angular impulse is $\\Delta L=\\tau\\Delta t=-3(2)=-6$ kg m² s⁻¹. Final angular momentum is $12-6=6$ kg m² s⁻¹.', 'Standard');
  add('A.4', 'A light horizontal beam is pivoted at its centre. A 20 N downward force acts 0.30 m to the left. What downward force 0.20 m to the right provides rotational equilibrium?', ['30 N', '13.3 N', '20 N', '60 N'], 'The opposite moments must match: $20(0.30)=F(0.20)$. Thus $F=30$ N. The pivot supplies the vertical force needed for translational equilibrium.', 'Standard');

  add('A.5', 'Frame S′ moves at $0.60c$ along +x relative to S, so $\\gamma=1.25$. An event has $x=4.0$ m and $ct=5.0$ m in S. What is $x′$?', ['1.25 m', '8.75 m', '3.20 m', '5.00 m'], 'Use $x′=\\gamma(x-vt)=\\gamma[x-(v/c)(ct)]$. Thus $x′=1.25[4.0-0.60(5.0)]=1.25$ m.', 'Challenge');
  add('A.5', 'Frame S′ moves at $0.60c$ along +x relative to S, so $\\gamma=1.25$. An event has $x=4.0$ m and $ct=5.0$ m in S. What is $ct′$?', ['3.25 m', '9.25 m', '5.00 m', '2.08 m'], 'Multiply the time transformation by $c$: $ct′=\\gamma[ct-(v/c)x]=1.25[5.0-0.60(4.0)]=3.25$ m.', 'Challenge');
  add('A.5', 'Two events are simultaneous in S and are separated by $\\Delta x=300$ m. S′ moves at $0.60c$ along +x, with $\\gamma=1.25$. Use $c=3.0\\times10^8$ m s⁻¹. What is $\\Delta t′$ for the second event minus the first?', ['−0.75 μs', '+0.75 μs', '0 μs', '−1.25 μs'], 'For $\\Delta t=0$, $\\Delta t′=-\\gamma v\\Delta x/c^2=-1.25(0.60)(300)/(3.0\\times10^8)=-0.75$ μs. The event at larger x occurs earlier in S′.', 'Challenge');
  add('A.5', 'Two events have $c\\Delta t=3$ m and $\\Delta x=5$ m. What can be concluded about a signal connecting them?', ['A signal would need to travel faster than light, so they cannot be causally connected.', 'A light signal can connect them.', 'An object travelling at $0.6c$ can connect them.', 'The events must occur at the same place in every frame.'], 'The separation is spacelike: $(\\Delta s)^2=3^2-5^2=-16$ m². Their required signal speed is $|\\Delta x/\\Delta t|=(5/3)c>c$.', 'Challenge');

  add('B.1', 'Equal masses of the same liquid at 80°C and 20°C are mixed in an insulated container of negligible heat capacity. No phase change occurs and specific heat capacity is constant. What is the final temperature?', ['50°C', '60°C', '40°C', '100°C'], 'Energy lost by the hot sample equals energy gained by the cool sample: $mc(80-T)=mc(T-20)$. Therefore $2T=100$ and $T=50$°C.', 'Standard');
  add('B.1', 'A 0.10 kg ice sample at −10°C becomes water at 20°C. Use $c_{ice}=2100$ J kg⁻¹ K⁻¹, $L_f=330000$ J kg⁻¹ and $c_{water}=4200$ J kg⁻¹ K⁻¹. Neglect losses. What energy is required?', ['43500 J', '33000 J', '35100 J', '41400 J'], 'Add three stages: warm ice $0.10(2100)(10)=2100$ J; melt $0.10(330000)=33000$ J; warm water $0.10(4200)(20)=8400$ J. Total is 43500 J.', 'Challenge');
  add('B.1', 'Black-body star X has twice the radius and half the temperature of star Y. What is $L_X/L_Y$?', ['1/4', '1/2', '4', '1/16'], 'Since $L=4\\pi R^2\\sigma T^4$, the luminosity ratio is $2^2(1/2)^4=4/16=1/4$.', 'Challenge');
  add('B.1', 'A 100 W heater warms 0.50 kg of liquid. Its temperature rises at 0.040 K s⁻¹, with negligible heat loss. What is its specific heat capacity?', ['5000 J kg⁻¹ K⁻¹', '1250 J kg⁻¹ K⁻¹', '2000 J kg⁻¹ K⁻¹', '20000 J kg⁻¹ K⁻¹'], 'From $P=mc(\\Delta T/\\Delta t)$, $c=P/[m(\\Delta T/\\Delta t)]=100/[0.50(0.040)]=5000$ J kg⁻¹ K⁻¹.', 'Challenge');

  add('B.2', 'A uniform-temperature planet with no atmosphere has $S=1360$ W m⁻², albedo 0.30 and emissivity 1. Use $\\sigma=5.67\\times10^{-8}$ W m⁻² K⁻⁴. What is its approximate equilibrium temperature?', ['255 K', '279 K', '360 K', '239 K'], 'The absorbed mean flux is $1360(0.70)/4=238$ W m⁻². Equating it to $\\sigma T^4$ gives $T=(238/5.67\\times10^{-8})^{1/4}\\approx255$ K.', 'Challenge');
  add('B.2', 'In the simple equilibrium equation $(1-a)S/4=\\varepsilon\\sigma T^4$, emissivity is halved with albedo and solar constant held fixed. By what factor does $T$ change?', ['$2^{1/4}$', '$1/2$', '$2$', '$2^{-1/4}$'], 'At fixed absorbed solar power, $T^4$ is inversely proportional to emissivity. Halving emissivity doubles $T^4$, so temperature increases by $2^{1/4}\\approx1.19$.', 'Challenge');
  add('B.2', 'Ice melts and exposes a darker ocean surface. Which sequence describes a possible positive feedback?', ['Albedo falls, solar absorption increases, warming promotes more melting.', 'Albedo rises, solar absorption increases, warming stops.', 'Albedo falls, solar absorption decreases, cooling promotes melting.', 'Emissivity necessarily becomes zero, so all radiation stops.'], 'Darker surfaces generally reflect less sunlight. Increased absorption can cause further warming and melting, amplifying the original change.', 'Standard');
  add('B.2', 'A planet of radius $R$ receives solar constant $S$ and has albedo $a$. Which expression gives the total absorbed solar power?', ['$(1-a)S\\pi R^2$', '$(1-a)S4\\pi R^2$', '$aS\\pi R^2$', '$S/(4\\pi R^2)$'], 'The intercepted power is solar irradiance times projected area, $S\\pi R^2$. The absorbed fraction is $1-a$. The factor $4\\pi R^2$ is used when distributing power over the entire spherical surface.', 'Standard');

  add('B.3', 'A fixed ideal-gas sample changes from 100 kPa, 2.0 L and 300 K to 400 K and 1.0 L. What is its final pressure?', ['267 kPa', '66.7 kPa', '150 kPa', '200 kPa'], 'For fixed gas amount, $P_1V_1/T_1=P_2V_2/T_2$. Thus $P_2=100(2.0)(400)/[300(1.0)]=267$ kPa to three significant figures.', 'Challenge');
  add('B.3', 'At fixed pressure, an ideal gas’s absolute temperature increases by a factor of four. What happens to its density?', ['It becomes one quarter.', 'It doubles.', 'It becomes four times as large.', 'It is unchanged.'], 'For a fixed molecular species, $P=\\rho RT/M$, where $M$ is molar mass. At fixed pressure, density is inversely proportional to absolute temperature.', 'Challenge');
  add('B.3', 'Two ideal gases are at the same temperature. Molecules of gas X have four times the mass of molecules of gas Y. What is $v_{rms,X}/v_{rms,Y}$?', ['1/2', '1/4', '2', '4'], 'Equal temperature gives equal mean translational kinetic energy. Since $v_{rms}\\propto1/\\sqrt{m}$, multiplying molecular mass by four halves rms speed.', 'Standard');
  add('B.3', 'What is the mean translational kinetic energy of one ideal-gas molecule at 300 K? Use $k_B=1.38\\times10^{-23}$ J K⁻¹.', ['$6.21\\times10^{-21}$ J', '$4.14\\times10^{-21}$ J', '$2.07\\times10^{-21}$ J', '$1.24\\times10^{-20}$ J'], 'Mean translational kinetic energy is $3k_BT/2=1.5(1.38\\times10^{-23})(300)=6.21\\times10^{-21}$ J.', 'Standard');

  add('B.4', 'A heat engine absorbs 800 J and rejects 500 J in each complete cycle. What are its net work output and efficiency?', ['300 J and 37.5%', '300 J and 60%', '1300 J and 62.5%', '500 J and 62.5%'], 'Over a cycle $\\Delta U=0$, so $W=Q_h-Q_c=800-500=300$ J. Efficiency is $W/Q_h=300/800=0.375$.', 'Challenge');
  add('B.4', 'An ideal monatomic gas is compressed reversibly and adiabatically to one eighth of its initial volume. What is the ratio of final to initial absolute temperature?', ['4', '8', '32', '1/4'], 'Combine $PV^{5/3}=constant$ and $PV=nRT$ to obtain $TV^{2/3}=constant$. Thus $T_2/T_1=(V_1/V_2)^{2/3}=8^{2/3}=4$.', 'Challenge');
  add('B.4', 'A system’s equally probable accessible microstates increase from 2 to 8. What is its entropy increase?', ['$k_B\\ln4$', '$k_B\\ln6$', '$4k_B$', '$k_B\\ln16$'], 'Entropy change is $k_B\\ln\\Omega_2-k_B\\ln\\Omega_1=k_B\\ln(8/2)=k_B\\ln4$. Entropy differences depend on the ratio of microstate counts.', 'Standard');
  add('B.4', 'A quantity of 300 J of heat passes directly from a reservoir at 600 K to a reservoir at 300 K without work extraction. What is the total entropy change of the two reservoirs?', ['+0.50 J K⁻¹', '0 J K⁻¹', '−0.50 J K⁻¹', '+1.50 J K⁻¹'], 'The hot reservoir loses entropy $300/600=0.50$ J K⁻¹; the cold gains $300/300=1.00$ J K⁻¹. Total is +0.50 J K⁻¹. The direct heat transfer is irreversible even though each reservoir’s change can be calculated using a reversible reference path.', 'Challenge');

  add('B.5', 'A 6 Ω resistor is in series with a parallel combination of 3 Ω and 6 Ω resistors. They are connected to an ideal 12 V source. What is the total current?', ['1.5 A', '0.80 A', '2.0 A', '6.0 A'], 'The parallel pair has resistance $3(6)/(3+6)=2$ Ω. Total resistance is $6+2=8$ Ω, so source current is $12/8=1.5$ A.', 'Challenge');
  add('B.5', 'A potential divider has a fixed resistor above an LDR, in series across a constant ideal voltage source. The output is measured across the LDR with an ideal voltmeter. What happens to output voltage as illumination increases?', ['It decreases.', 'It increases.', 'It is unchanged.', 'It reverses polarity.'], 'More light lowers the LDR resistance. The output fraction is $R_{LDR}/(R_{fixed}+R_{LDR})$, which decreases when $R_{LDR}$ decreases.', 'Challenge');
  add('B.5', 'A cell of emf 12 V and internal resistance 2 Ω is connected to a 4 Ω resistor. What power is dissipated inside the cell?', ['8 W', '16 W', '24 W', '72 W'], 'Current is $I=12/(4+2)=2$ A. Power in the internal resistance is $I^2r=2^2(2)=8$ W; external power is instead 16 W.', 'Challenge');
  add('B.5', 'A wire is stretched so its length doubles while its volume and resistivity stay constant. What is the ratio of final to initial resistance?', ['4', '2', '1/2', '1'], 'Constant volume $AL$ means cross-sectional area halves. Since $R=\\rho L/A$, doubling length and halving area multiply resistance by four.', 'Challenge');
  globalThis.QUESTION_AB = bank;
})();
